package daripher.skilltree.capability.skill;

import daripher.skilltree.data.reloader.SkillsReloader;
import daripher.skilltree.skill.PassiveSkill;
import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.StringTag;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;

import javax.annotation.Nonnull;
import java.util.UUID;

public class PlayerSkills implements IPlayerSkills {
    private static final UUID TREE_VERSION = UUID.fromString("fd21c2a9-7ab5-4a1e-b06d-ddb87b56047f");
    private final NonNullList<PassiveSkill> skills = NonNullList.create();
    private int skillPoints;
    private boolean treeReset;

    @Override
    public NonNullList<PassiveSkill> getPlayerSkills() {
        return skills;
    }

    @Override
    public int getSkillPoints() {
        return skillPoints;
    }

    @Override
    public void setSkillPoints(int skillPoints) {
        this.skillPoints = skillPoints;
    }

    @Override
    public void grantSkillPoints(int skillPoints) {
        this.skillPoints += skillPoints;
    }

    @Override
    public boolean learnSkill(@Nonnull PassiveSkill passiveSkill) {
        if (skillPoints == 0) {
            return false;
        }
        if (skills.contains(passiveSkill)) {
            return false;
        }
        skillPoints--;
        return skills.add(passiveSkill);
    }

    @Override
    public boolean grantSkill(PassiveSkill passiveSkill) {
        if (skills.contains(passiveSkill)) {
            return false;
        }
        return skills.add(passiveSkill);
    }

    @Override
    public boolean isTreeReset() {
        return treeReset;
    }

    @Override
    public void setTreeReset(boolean reset) {
        treeReset = reset;
    }

    @Override
    public void resetTree(ServerPlayer player) {
        skillPoints += getPlayerSkills().size();
        getPlayerSkills().forEach(skill -> skill.remove(player));
        getPlayerSkills().clear();
    }

    @Override
    public CompoundTag serializeNBT() {
        CompoundTag tag = new CompoundTag();
        tag.putUUID("TreeVersion", TREE_VERSION);
        tag.putInt("Points", skillPoints);
        tag.putBoolean("TreeReset", treeReset);
        ListTag skillsTag = new ListTag();
        skills.forEach(skill -> skillsTag.add(StringTag.valueOf(skill.getId().toString())));
        tag.put("Skills", skillsTag);
        return tag;
    }

    @Override
    public void deserializeNBT(CompoundTag tag) {
        skills.clear();
        UUID treeVersion = tag.hasUUID("TreeVersion") ? tag.getUUID("TreeVersion") : null;
        skillPoints = tag.getInt("Points");
        ListTag skillsTag = tag.getList("Skills", Tag.TAG_STRING);
        if (!TREE_VERSION.equals(treeVersion)) {
            skillPoints += skillsTag.size();
            treeReset = true;
            return;
        }
        for (Tag skillTag : skillsTag) {
            ResourceLocation skillId = ResourceLocation.parse(skillTag.getAsString());
            PassiveSkill passiveSkill = SkillsReloader.getSkillById(skillId);
            if (passiveSkill == null || passiveSkill.isInvalid()) {
                skills.clear();
                treeReset = true;
                skillPoints += skillsTag.size();
                return;
            }
            skills.add(passiveSkill);
        }
    }
}

package daripher.skilltree.capability.skill;

import daripher.skilltree.SkillTreeMod;
import daripher.skilltree.network.NetworkDispatcher;
import daripher.skilltree.network.message.SyncPlayerSkillsMessage;
import daripher.skilltree.network.message.SyncServerDataMessage;
import net.minecraft.ChatFormatting;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityManager;
import net.minecraftforge.common.capabilities.CapabilityToken;
import net.minecraftforge.common.capabilities.ICapabilitySerializable;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.event.entity.EntityJoinLevelEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod.EventBusSubscriber;
import net.minecraftforge.network.PacketDistributor;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

@EventBusSubscriber(modid = SkillTreeMod.MOD_ID)
public class PlayerSkillsProvider implements ICapabilitySerializable<CompoundTag> {
    private static final ResourceLocation CAPABILITY_ID = ResourceLocation.fromNamespaceAndPath(SkillTreeMod.MOD_ID, "player_skills");
    private static final Capability<IPlayerSkills> CAPABILITY = CapabilityManager.get(new CapabilityToken<>() {
    });
    private final LazyOptional<IPlayerSkills> optionalCapability = LazyOptional.of(PlayerSkills::new);

    @SubscribeEvent
    public static void attachCapability(AttachCapabilitiesEvent<Entity> event) {
        if (!(event.getObject() instanceof Player)) {
            return;
        }
        PlayerSkillsProvider provider = new PlayerSkillsProvider();
        event.addCapability(CAPABILITY_ID, provider);
    }

    @SubscribeEvent
    public static void persistThroughDeath(PlayerEvent.Clone event) {
        if (event.getEntity().level().isClientSide) {
            return;
        }
        event.getOriginal().reviveCaps();
        IPlayerSkills originalData = get(event.getOriginal());
        IPlayerSkills cloneData = get(event.getEntity());
        cloneData.deserializeNBT(originalData.serializeNBT());
        event.getOriginal().invalidateCaps();
    }

    @SubscribeEvent
    public static void syncSkills(PlayerLoggedInEvent event) {
        if (event.getEntity().level().isClientSide) {
            return;
        }
        NetworkDispatcher.network_channel.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) event.getEntity()), new SyncServerDataMessage());
    }

    @SubscribeEvent(priority = EventPriority.LOWEST)
    public static void restoreSkillsAttributeModifiers(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof ServerPlayer player)) {
            return;
        }
        get(player).getPlayerSkills().forEach(skill -> skill.learn(player, false));
    }

    @SubscribeEvent
    public static void sendTreeResetMessage(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        if (event.getEntity().level().isClientSide) {
            return;
        }
        IPlayerSkills capability = get(player);
        if (capability.isTreeReset()) {
            player.sendSystemMessage(Component.translatable("skilltree.message.reset").withStyle(ChatFormatting.YELLOW));
            capability.setTreeReset(false);
        }
    }

    @SubscribeEvent
    public static void syncPlayerSkills(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof ServerPlayer player)) {
            return;
        }
        NetworkDispatcher.network_channel.send(PacketDistributor.PLAYER.with(() -> player), new SyncPlayerSkillsMessage(player));
    }

    public static @NotNull IPlayerSkills get(Player player) {
        return player.getCapability(CAPABILITY).orElseThrow(NullPointerException::new);
    }

    public static boolean hasSkills(@NotNull Player player) {
        return player.getCapability(CAPABILITY).isPresent();
    }

    @Override
    public <T> @NotNull LazyOptional<T> getCapability(@NotNull Capability<T> cap, @Nullable Direction side) {
        return cap == CAPABILITY ? optionalCapability.cast() : LazyOptional.empty();
    }

    @Override
    public CompoundTag serializeNBT() {
        return optionalCapability.orElseThrow(NullPointerException::new).serializeNBT();
    }

    @Override
    public void deserializeNBT(CompoundTag compoundTag) {
        optionalCapability.orElseThrow(NullPointerException::new).deserializeNBT(compoundTag);
    }
}

package daripher.skilltree.data.reloader;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonElement;
import daripher.skilltree.SkillTreeMod;
import daripher.skilltree.data.serializers.SkillBonusSerializer;
import daripher.skilltree.data.serializers.SkillRequirementSerializer;
import daripher.skilltree.network.NetworkHelper;
import daripher.skilltree.skill.PassiveSkill;
import daripher.skilltree.skill.bonus.SkillBonus;
import daripher.skilltree.skill.requirement.SkillRequirement;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.ResourceManager;
import net.minecraft.server.packs.resources.SimpleJsonResourceReloadListener;
import net.minecraft.util.profiling.ProfilerFiller;
import net.minecraftforge.event.AddReloadListenerEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod.EventBusSubscriber;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;
import java.util.HashMap;
import java.util.Map;

@EventBusSubscriber(modid = SkillTreeMod.MOD_ID)
public class SkillsReloader extends SimpleJsonResourceReloadListener {
    public static final Gson GSON = new GsonBuilder().registerTypeAdapter(ResourceLocation.class, new ResourceLocation.Serializer())
            .registerTypeAdapter(SkillBonus.class, new SkillBonusSerializer())
            .registerTypeAdapter(SkillRequirement.class, new SkillRequirementSerializer())
            .registerTypeAdapter(MutableComponent.class, new Component.Serializer()).setPrettyPrinting().create();
    private static final Map<ResourceLocation, PassiveSkill> SKILLS = new HashMap<>();

    public SkillsReloader() {
        super(GSON, "skills");
    }

    @SubscribeEvent
    public static void reloadSkills(AddReloadListenerEvent event) {
        event.addListener(new SkillsReloader());
    }

    public static Map<ResourceLocation, PassiveSkill> getSkills() {
        return SKILLS;
    }

    public static @Nullable PassiveSkill getSkillById(ResourceLocation id) {
        return SKILLS.get(id);
    }

    public static void loadFromByteBuf(FriendlyByteBuf buf) {
        SKILLS.clear();
        NetworkHelper.readPassiveSkills(buf).forEach(s -> SKILLS.put(s.getId(), s));
    }

    @Override
    protected void apply(Map<ResourceLocation, JsonElement> map, @NotNull ResourceManager resourceManager, @NotNull ProfilerFiller profilerFiller) {
        SKILLS.clear();
        map.forEach(this::readSkill);
    }

    protected void readSkill(ResourceLocation id, JsonElement json) {
        try {
            PassiveSkill skill = GSON.fromJson(json, PassiveSkill.class);
            SKILLS.put(skill.getId(), skill);
        } catch (Exception exception) {
            String errorMessage = "Couldn't load passive skill: " + id;
            SkillTreeMod.LOGGER.error(errorMessage, exception);
        }
    }
}

package daripher.skilltree.event;

import daripher.skilltree.SkillTreeMod;
import daripher.skilltree.skill.bonus.predicate.item.EquipmentPredicate;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.alchemy.PotionUtils;
import net.minecraftforge.event.entity.living.LivingAttackEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.ArrayList;
import java.util.List;

@Mod.EventBusSubscriber(modid = SkillTreeMod.MOD_ID)
public class PoisonedWeaponEvents {
    public static final String WEAPON_EFFECTS_TAG_NAME = "poisoned_weapon_effects";
    public static final String POISON_USES_LEFT_TAG_NAME = "poisoned_weapon_uses_left";

    @SubscribeEvent
    public static void applyPoisonedWeaponEffect(LivingAttackEvent event) {
        if (!(event.getSource().getEntity() instanceof Player player)) {
            return;
        }
        ItemStack mainHandItem = player.getMainHandItem();
        if (!EquipmentPredicate.isMeleeWeapon(mainHandItem)) {
            return;
        }
        if (!hasPoison(mainHandItem)) {
            return;
        }
        getPoisonedWeaponEffects(mainHandItem).forEach(pEffectInstance -> event.getEntity().addEffect(pEffectInstance, player));
        if (!hasInfinitePoisonUses(mainHandItem)) {
            consumePoisonStack(mainHandItem);
        }
    }

    public static void setPoisonedWeaponEffects(ItemStack itemStack, ItemStack potionStack, int maxUses) {
        List<MobEffectInstance> potionEffects = PotionUtils.getMobEffects(potionStack);
        CompoundTag itemTag = itemStack.getOrCreateTag();
        ListTag effectsTagList = new ListTag();
        potionEffects.stream().map(effectInstance -> effectInstance.save(new CompoundTag())).forEach(effectsTagList::add);
        itemTag.put(WEAPON_EFFECTS_TAG_NAME, effectsTagList);
        itemTag.putInt(POISON_USES_LEFT_TAG_NAME, maxUses);
    }

    public static boolean hasPoison(ItemStack itemStack) {
        if (!itemStack.hasTag()) {
            return false;
        }
        CompoundTag itemTag = itemStack.getOrCreateTag();
        if (!itemTag.contains(WEAPON_EFFECTS_TAG_NAME, Tag.TAG_LIST)) {
            return false;
        }
        if (itemTag.getList(WEAPON_EFFECTS_TAG_NAME, Tag.TAG_COMPOUND).isEmpty()) {
            return false;
        }
        return hasInfinitePoisonUses(itemStack) || getPoisonUses(itemStack) > 0;
    }

    public static boolean hasInfinitePoisonUses(ItemStack itemStack) {
        int usesLeft = getPoisonUses(itemStack);
        return usesLeft == -1;
    }

    public static int getPoisonUses(ItemStack itemStack) {
        CompoundTag itemTag = itemStack.getOrCreateTag();
        return itemTag.getInt(POISON_USES_LEFT_TAG_NAME);
    }

    public static List<MobEffectInstance> getPoisonedWeaponEffects(ItemStack itemStack) {
        if (!hasPoison(itemStack)) {
            return List.of();
        }
        CompoundTag itemTag = itemStack.getOrCreateTag();
        List<MobEffectInstance> effects = new ArrayList<>();
        ListTag effectsListTag = itemTag.getList(WEAPON_EFFECTS_TAG_NAME, Tag.TAG_COMPOUND);
        effectsListTag.stream().map(CompoundTag.class::cast).map(MobEffectInstance::load).forEach(effects::add);
        return effects;
    }

    private static void consumePoisonStack(ItemStack itemStack) {
        if (!hasPoison(itemStack)) {
            return;
        }
        CompoundTag itemTag = itemStack.getOrCreateTag();
        int usesLeft = getPoisonUses(itemStack) - 1;
        if (usesLeft == 0) {
            clearWeaponEffects(itemStack);
            return;
        }
        itemTag.putInt(POISON_USES_LEFT_TAG_NAME, usesLeft);
    }

    private static void clearWeaponEffects(ItemStack itemStack) {
        CompoundTag itemTag = itemStack.getOrCreateTag();
        itemTag.remove(WEAPON_EFFECTS_TAG_NAME);
        itemTag.remove(POISON_USES_LEFT_TAG_NAME);
    }
}

package daripher.skilltree.inventory.menu;

import daripher.skilltree.init.PSTBlocks;
import daripher.skilltree.init.PSTMenuTypes;
import daripher.skilltree.init.PSTRecipeTypes;
import daripher.skilltree.inventory.slot.WorkbenchBaseSlot;
import daripher.skilltree.inventory.slot.WorkbenchResultSlot;
import daripher.skilltree.inventory.slot.WorkbenchIngredientSlot;
import daripher.skilltree.recipe.workbench.AbstractWorkbenchRecipe;
import daripher.skilltree.recipe.workbench.WorkbenchVanillaCraftingRecipe;
import daripher.skilltree.skill.SkillBonusProvider;
import daripher.skilltree.skill.bonus.player.CraftedItemBonusBonus;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.CraftingRecipe;
import net.minecraft.world.item.crafting.RecipeType;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class WorkbenchMenu extends AbstractContainerMenu {
    private static final List<AbstractWorkbenchRecipe> WORKBENCH_RECIPE_CACHE = new ArrayList<>();
    private static final int RESULT_SLOT = 0;
    private static final int CRAFT_SLOT_START = RESULT_SLOT + 1;
    private static final int CRAFT_SLOT_END = CRAFT_SLOT_START + 10;
    private static final int INV_SLOT_START = CRAFT_SLOT_END;
    private static final int INV_SLOT_END = INV_SLOT_START + 27;
    private static final int HOTBAR_SLOT_START = INV_SLOT_END;
    private static final int HOTBAR_SLOT_END = HOTBAR_SLOT_START + 9;
    private final WorkbenchContainer workbenchContainer;
    private final ResultContainer resultSlots;
    private final ContainerLevelAccess levelAccess;
    private final Player player;
    private final DataSlot selectedRecipeIndex;
    private List<AbstractWorkbenchRecipe> selectedRecipes = new ArrayList<>();
    private @NotNull ItemStack prevInput = ItemStack.EMPTY;
    private final Level level;
    private @Nullable Runnable recipeListUpdateListener;

    public WorkbenchMenu(int containerId, Inventory playerInventory) {
        this(containerId, playerInventory, ContainerLevelAccess.NULL);
    }

    public WorkbenchMenu(int containerId, Inventory playerInventory, ContainerLevelAccess levelAccess) {
        super(PSTMenuTypes.ARTISAN_WORKBENCH.get(), containerId);
        this.selectedRecipeIndex = DataSlot.standalone();
        this.workbenchContainer = new WorkbenchContainer(this);
        this.resultSlots = new ResultContainer();
        this.levelAccess = levelAccess;
        this.player = playerInventory.player;
        this.level = player.level();
        addSlot(new WorkbenchResultSlot(playerInventory.player, workbenchContainer, resultSlots, 0, 143, 129));
        addSlot(new WorkbenchBaseSlot(workbenchContainer, 0, 8, 120));
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 5; ++j) {
                if (i == 0 && j == 0) {
                    continue;
                }
                addSlot(new WorkbenchIngredientSlot(workbenchContainer, j + i * 5, 8 + j * 18, 120 + i * 18, j + i * 5 - 1));
            }
        }
        for (int i = 0; i < 9; ++i) {
            addSlot(new Slot(playerInventory, i, 8 + i * 18, 218));
        }
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 9; ++j) {
                addSlot(new Slot(playerInventory, j + i * 9 + 9, 8 + j * 18, 160 + i * 18));
            }
        }
        addDataSlot(selectedRecipeIndex);
        setupRecipeList();
    }

    @Override
    public @NotNull ItemStack quickMoveStack(@NotNull Player player, int slotIndex) {
        ItemStack movedStack = ItemStack.EMPTY;
        Slot slot = slots.get(slotIndex);
        if (!slot.hasItem()) {
            return movedStack;
        }
        ItemStack clickedStack = slot.getItem();
        movedStack = clickedStack.copy();
        if (slotIndex == RESULT_SLOT) {
            levelAccess.execute((level, blockPos) -> clickedStack.getItem().onCraftedBy(clickedStack, level, player));
            if (!moveItemStackTo(clickedStack, INV_SLOT_START, HOTBAR_SLOT_END, true)) {
                return ItemStack.EMPTY;
            }
            slot.onQuickCraft(clickedStack, movedStack);
        } else if (slotIndex >= INV_SLOT_START && slotIndex < HOTBAR_SLOT_END) {
            if (!moveItemStackTo(clickedStack, CRAFT_SLOT_START, CRAFT_SLOT_END, false)) {
                if (slotIndex < INV_SLOT_END) {
                    if (!moveItemStackTo(clickedStack, HOTBAR_SLOT_START, HOTBAR_SLOT_END, false)) {
                        return ItemStack.EMPTY;
                    }
                } else if (!moveItemStackTo(clickedStack, INV_SLOT_START, INV_SLOT_END, false)) {
                    return ItemStack.EMPTY;
                }
            }
        } else if (!moveItemStackTo(clickedStack, INV_SLOT_START, HOTBAR_SLOT_END, false)) {
            return ItemStack.EMPTY;
        }
        if (clickedStack.isEmpty()) {
            slot.setByPlayer(ItemStack.EMPTY);
        } else {
            slot.setChanged();
        }
        if (clickedStack.getCount() == movedStack.getCount()) {
            return ItemStack.EMPTY;
        }
        slot.onTake(player, clickedStack);
        if (slotIndex == 0) {
            player.drop(clickedStack, false);
        }
        return movedStack;
    }

    @Override
    public void removed(@NotNull Player player) {
        super.removed(player);
        levelAccess.execute((level, blockPos) -> clearContainer(player, workbenchContainer));
    }

    @Override
    public boolean stillValid(@NotNull Player player) {
        return stillValid(levelAccess, player, PSTBlocks.WORKBENCH.get());
    }

    @Override
    public boolean clickMenuButton(@NotNull Player player, int id) {
        if (id == -1) {
            selectedRecipeIndex.set(id);
            setupRecipeList();
        }
        if (isValidRecipeIndex(id)) {
            selectedRecipeIndex.set(id);
            AbstractWorkbenchRecipe selectedRecipe = getSelectedRecipe();
            if (selectedRecipe != null) {
                updateCraftingResult(selectedRecipe);
            }
        }
        return true;
    }

    private boolean isValidRecipeIndex(int recipeIndex) {
        return recipeIndex >= 0 && recipeIndex < selectedRecipes.size();
    }

    @Override
    public void slotsChanged(@NotNull Container container) {
        updateSelectedRecipe();
    }

    private void updateSelectedRecipe() {
        ItemStack input = workbenchContainer.getBaseItem();
        AbstractWorkbenchRecipe selectedRecipe = getSelectedRecipe();
        if (selectedRecipe != null) {
            updateCraftingResult(selectedRecipe);
            return;
        }
        if (!ItemStack.isSameItemSameTags(input, prevInput)) {
            setupRecipeList();
            prevInput = input.copy();
        }
        broadcastChanges();
        if (recipeListUpdateListener != null) {
            recipeListUpdateListener.run();
        }
    }

    public void setRecipeListUpdateListener(@Nullable Runnable recipeListUpdateListener) {
        this.recipeListUpdateListener = recipeListUpdateListener;
    }

    private void updateCraftingResult(AbstractWorkbenchRecipe selectedRecipe) {
        if (!selectedRecipe.matches(workbenchContainer, level)) {
            resultSlots.setItem(0, ItemStack.EMPTY);
        } else {
            if (!level.isClientSide) {
                ItemStack craftResult = selectedRecipe.assemble(workbenchContainer, level.registryAccess());
                addCraftingBonuses(craftResult);
                resultSlots.setRecipeUsed(selectedRecipe);
                resultSlots.setItem(0, craftResult);
            }
        }
    }

    public void addCraftingBonuses(ItemStack craftResult) {
        SkillBonusProvider.getMergedSkillBonuses(player, CraftedItemBonusBonus.class).forEach(bonus -> bonus.itemCrafted(craftResult));
    }

    private void setupRecipeList() {
        selectedRecipeIndex.set(-1);
        resultSlots.setItem(0, ItemStack.EMPTY);
        selectedRecipes = getAllWorkbenchRecipes().stream().filter(this::shouldDisplayRecipe)
                .sorted(Comparator.comparing(AbstractWorkbenchRecipe::getId)).toList();
    }

    private List<AbstractWorkbenchRecipe> getAllWorkbenchRecipes() {
        if (!WORKBENCH_RECIPE_CACHE.isEmpty()) {
            return WORKBENCH_RECIPE_CACHE;
        }
        List<CraftingRecipe> vanillaCraftingRecipes = level.getRecipeManager().getAllRecipesFor(RecipeType.CRAFTING).stream()
                .filter(recipe -> !recipe.getResultItem(level.registryAccess()).isEmpty()).toList();
        WORKBENCH_RECIPE_CACHE.addAll(level.getRecipeManager().getAllRecipesFor(PSTRecipeTypes.WORKBENCH));
        WORKBENCH_RECIPE_CACHE.addAll(vanillaCraftingRecipes.stream().map(this::convertVanillaRecipe).toList());
        return WORKBENCH_RECIPE_CACHE;
    }

    private AbstractWorkbenchRecipe convertVanillaRecipe(CraftingRecipe craftingRecipe) {
        return new WorkbenchVanillaCraftingRecipe(craftingRecipe, level.registryAccess());
    }

    private boolean shouldDisplayRecipe(AbstractWorkbenchRecipe recipe) {
        if (recipe.isLockedFor(player)) {
            return false;
        }
        return workbenchContainer.getBaseItem().isEmpty() || recipe.isValidBaseItem(workbenchContainer.getBaseItem());
    }

    public Player getPlayer() {
        return player;
    }

    public List<AbstractWorkbenchRecipe> getSelectedRecipes() {
        return selectedRecipes;
    }

    public int getSelectedRecipeIndex() {
        return selectedRecipeIndex.get();
    }

    public WorkbenchContainer getWorkbenchContainer() {
        return workbenchContainer;
    }

    public ItemStack getResultItem() {
        return resultSlots.getItem(0);
    }

    public @Nullable AbstractWorkbenchRecipe getSelectedRecipe() {
        if (selectedRecipes.isEmpty()) {
            return null;
        }
        int index = selectedRecipeIndex.get();
        if (index >= selectedRecipes.size() || index < 0) {
            return null;
        }
        return selectedRecipes.get(index);
    }
}

package daripher.skilltree.recipe.workbench;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import daripher.skilltree.client.tooltip.TooltipHelper;
import daripher.skilltree.data.serializers.SerializationHelper;
import daripher.skilltree.init.PSTRecipeSerializers;
import daripher.skilltree.inventory.menu.WorkbenchContainer;
import daripher.skilltree.network.NetworkHelper;
import daripher.skilltree.skill.bonus.item.ItemBonus;
import daripher.skilltree.skill.bonus.item.ItemBonusHandler;
import daripher.skilltree.skill.bonus.predicate.item.ItemStackPredicate;
import net.minecraft.core.RegistryAccess;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.world.item.crafting.RecipeSerializer;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class WorkbenchUpgradeBonusRecipe extends AbstractWorkbenchRecipe {
    private final ItemStackPredicate baseItemStackPredicate;
    private final Map<Ingredient, Integer> additionalIngredients;
    private final ItemBonus<?> itemBonus;

    public WorkbenchUpgradeBonusRecipe(ResourceLocation id, ItemStackPredicate baseItemStackPredicate, Map<Ingredient, Integer> additionalIngredients, boolean requiresPassiveSkill, ItemBonus<?> itemBonus) {
        super(id, requiresPassiveSkill);
        this.baseItemStackPredicate = baseItemStackPredicate;
        this.itemBonus = itemBonus;
        this.additionalIngredients = additionalIngredients;
    }

    @Override
    public @NotNull ItemStack assemble(@NotNull WorkbenchContainer container, @NotNull RegistryAccess registryAccess) {
        return getResult(container);
    }

    @Override
    public boolean isValidBaseItem(ItemStack itemStack) {
        return baseItemStackPredicate.test(itemStack);
    }

    @Override
    public Map<Ingredient, Integer> getAdditionalIngredients(ItemStack baseIngredient) {
        return additionalIngredients;
    }

    public Map<Ingredient, Integer> getAdditionalIngredients() {
        return additionalIngredients;
    }

    @Override
    public Component getShortDescription() {
        Component itemTooltip = baseItemStackPredicate.getTooltip("plural");
        return Component.translatable(getDescriptionId(), itemBonus.getFullTooltip().get(0), itemTooltip);
    }

    @Override
    public List<Component> getFullDescription() {
        List<Component> fullDescription = new ArrayList<>();
        Style style = TooltipHelper.getItemUpgradeStyle();
        for (MutableComponent mutableComponent : itemBonus.getFullTooltip()) {
            fullDescription.add(mutableComponent.withStyle(style));
        }
        Component itemTooltip = baseItemStackPredicate.getTooltip("plural");
        itemTooltip = Component.literal("[").append(itemTooltip).append("]");
        fullDescription.add(itemTooltip);
        return fullDescription;
    }

    @Override
    public @NotNull ItemStack getResult(WorkbenchContainer workbenchContainer) {
        ItemStack baseItem = workbenchContainer.getBaseItem().copy();
        Player player = workbenchContainer.getPlayer();
        int craftedBonusLimit = ItemBonusHandler.getCraftedBonusLimit(baseItem, player);
        if (craftedBonusLimit <= 0) {
            return baseItem;
        }
        List<ItemBonus<?>> originalBonuses = new ArrayList<>(ItemBonusHandler.getItemBonuses(baseItem));
        while (craftedBonusLimit <= originalBonuses.size()) {
            originalBonuses.remove(0);
        }
        originalBonuses.add(itemBonus.copy());
        ItemBonusHandler.setUpgradeBonuses(baseItem, originalBonuses);
        return baseItem;
    }

    @Override
    public int requiredBaseItemAmount() {
        return 1;
    }

    @Override
    public Pair<Ingredient, Integer> getBaseIngredient() {
        return null;
    }

    @Override
    public @NotNull RecipeSerializer<?> getSerializer() {
        return PSTRecipeSerializers.WORKBENCH_ITEM_BONUS.get();
    }

    public static class Serializer implements RecipeSerializer<WorkbenchUpgradeBonusRecipe> {
        @Override
        public @NotNull WorkbenchUpgradeBonusRecipe fromJson(@NotNull ResourceLocation id, @NotNull JsonObject jsonObject) {
            ItemStackPredicate baseItemStackPredicate = SerializationHelper.deserializeItemPredicate(jsonObject, "base_item_condition");
            ItemBonus<?> itemBonus = SerializationHelper.deserializeItemBonus(jsonObject);
            boolean requiresPassiveSkill = jsonObject.get("requires_passive_skill").getAsBoolean();
            Map<Ingredient, Integer> additionalIngredients = new HashMap<>();
            JsonArray ingredientsJson = jsonObject.getAsJsonArray("additionalIngredients");
            for (JsonElement jsonElement : ingredientsJson) {
                Ingredient ingredient = Ingredient.fromJson(jsonElement.getAsJsonObject().get("ingredient"));
                int requiredAmount = jsonElement.getAsJsonObject().get("required_amount").getAsInt();
                additionalIngredients.put(ingredient, requiredAmount);
            }
            return new WorkbenchUpgradeBonusRecipe(id, baseItemStackPredicate, additionalIngredients, requiresPassiveSkill, itemBonus);
        }

        @Override
        public @Nullable WorkbenchUpgradeBonusRecipe fromNetwork(@NotNull ResourceLocation id, @NotNull FriendlyByteBuf buf) {
            ItemStackPredicate baseItemStackPredicate = NetworkHelper.readItemPredicate(buf);
            ItemBonus<?> itemBonus = NetworkHelper.readItemBonus(buf);
            boolean requiresPassiveSkill = buf.readBoolean();
            Map<Ingredient, Integer> additionalIngredients = new HashMap<>();
            int ingredientsCount = buf.readInt();
            for (int i = 0; i < ingredientsCount; i++) {
                additionalIngredients.put(Ingredient.fromNetwork(buf), buf.readInt());
            }
            return new WorkbenchUpgradeBonusRecipe(id, baseItemStackPredicate, additionalIngredients, requiresPassiveSkill, itemBonus);
        }

        @Override
        public void toNetwork(@NotNull FriendlyByteBuf buf, @NotNull WorkbenchUpgradeBonusRecipe recipe) {
            NetworkHelper.writeItemPredicate(buf, recipe.baseItemStackPredicate);
            NetworkHelper.writeItemBonus(buf, recipe.itemBonus);
            buf.writeBoolean(recipe.hasPassiveSkillRequirement());
            int ingredientsCount = recipe.getAdditionalIngredients().size();
            buf.writeInt(ingredientsCount);
            recipe.getAdditionalIngredients().forEach((ingredient, requiredAmount) -> {
                ingredient.toNetwork(buf);
                buf.writeInt(requiredAmount);
            });
        }
    }
}

package daripher.skilltree.recipe.workbench;

import com.google.gson.JsonObject;
import daripher.skilltree.event.PoisonedWeaponEvents;
import daripher.skilltree.init.PSTRecipeSerializers;
import daripher.skilltree.inventory.menu.WorkbenchContainer;
import daripher.skilltree.skill.bonus.predicate.item.EquipmentPredicate;
import net.minecraft.core.RegistryAccess;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.effect.MobEffectCategory;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.alchemy.Potion;
import net.minecraft.world.item.alchemy.PotionUtils;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraftforge.registries.ForgeRegistries;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

public class WorkbenchWeaponPoisoningRecipe extends AbstractWorkbenchRecipe {
    private final int maxUses;

    public WorkbenchWeaponPoisoningRecipe(ResourceLocation id, boolean requiresPassiveSkill, int maxUses) {
        super(id, requiresPassiveSkill);
        this.maxUses = maxUses;
    }

    @Override
    public @NotNull ItemStack assemble(@NotNull WorkbenchContainer container, @NotNull RegistryAccess registryAccess) {
        return getResult(container);
    }

    @Override
    public boolean isValidBaseItem(ItemStack itemStack) {
        return EquipmentPredicate.isMeleeWeapon(itemStack);
    }

    @Override
    public boolean isValidIngredient(ItemStack itemStack) {
        return isValidPoison(itemStack);
    }

    private boolean isValidPoison(ItemStack itemStack) {
        Stream<MobEffectInstance> effectsStream = PotionUtils.getMobEffects(itemStack).stream();
        return effectsStream.anyMatch(mobEffectInstance -> mobEffectInstance.getEffect().getCategory() == MobEffectCategory.HARMFUL);
    }

    @Override
    public Pair<Ingredient, Integer> getBaseIngredient() {
        return Pair.of(getMeleeWeaponIngredient(), 1);
    }

    private Ingredient getMeleeWeaponIngredient() {
        Collection<Item> items = ForgeRegistries.ITEMS.getValues();
        Stream<ItemStack> meleeWeapons = items.stream().map(ItemStack::new).filter(EquipmentPredicate::isMeleeWeapon);
        return Ingredient.of(meleeWeapons.toList().toArray(new ItemStack[0]));
    }

    @Override
    public Map<Ingredient, Integer> getAdditionalIngredients(ItemStack baseIngredient) {
        return Map.of(getPoisonIngredient(), 1);
    }

    private Ingredient getPoisonIngredient() {
        Item baseItem = Items.POTION;
        Collection<Potion> availablePotions = ForgeRegistries.POTIONS.getValues();
        Stream<Potion> harmfulPotions = availablePotions.stream().filter(WorkbenchWeaponPoisoningRecipe::isHarmfulPotion);
        Stream<ItemStack> suitablePotionStacks = harmfulPotions.map(potion -> getPotionStack(baseItem, potion));
        return Ingredient.of(suitablePotionStacks.toList().toArray(new ItemStack[0]));
    }

    private static boolean isHarmfulPotion(Potion potion) {
        List<MobEffectInstance> effects = potion.getEffects();
        for (MobEffectInstance mobEffectInstance : effects) {
            if (mobEffectInstance.getEffect().getCategory() == MobEffectCategory.HARMFUL) {
                return true;
            }
        }
        return false;
    }

    private static @NotNull ItemStack getPotionStack(Item baseItem, Potion potion) {
        ItemStack itemStack = new ItemStack(baseItem);
        PotionUtils.setPotion(itemStack, potion);
        return itemStack;
    }

    @Override
    public Component getShortDescription() {
        return Component.translatable(getDescriptionId());
    }

    @Override
    public @NotNull ItemStack getResult(WorkbenchContainer workbenchContainer) {
        ItemStack weaponStack = workbenchContainer.getBaseItem();
        ItemStack potionStack = workbenchContainer.getItem(1);
        ItemStack resultItemStack = new ItemStack(weaponStack.getItem());
        PoisonedWeaponEvents.setPoisonedWeaponEffects(resultItemStack, potionStack, maxUses);
        return resultItemStack;
    }

    @Override
    public int requiredBaseItemAmount() {
        return 1;
    }

    @Override
    public @NotNull RecipeSerializer<?> getSerializer() {
        return PSTRecipeSerializers.WORKBENCH_WEAPON_POISONING.get();
    }

    public static class Serializer implements RecipeSerializer<WorkbenchWeaponPoisoningRecipe> {
        @Override
        public @NotNull WorkbenchWeaponPoisoningRecipe fromJson(@NotNull ResourceLocation id, @NotNull JsonObject jsonObject) {
            boolean requiresPassiveSkill = jsonObject.get("requires_passive_skill").getAsBoolean();
            int maxUses = jsonObject.get("max_uses").getAsInt();
            return new WorkbenchWeaponPoisoningRecipe(id, requiresPassiveSkill, maxUses);
        }

        @Override
        public @Nullable WorkbenchWeaponPoisoningRecipe fromNetwork(@NotNull ResourceLocation id, @NotNull FriendlyByteBuf buf) {
            boolean requiresPassiveSkill = buf.readBoolean();
            int maxUses = buf.readInt();
            return new WorkbenchWeaponPoisoningRecipe(id, requiresPassiveSkill, maxUses);
        }

        @Override
        public void toNetwork(@NotNull FriendlyByteBuf buf, @NotNull WorkbenchWeaponPoisoningRecipe recipe) {
            buf.writeBoolean(recipe.hasPassiveSkillRequirement());
            buf.writeInt(recipe.maxUses);
        }
    }
}

package daripher.skilltree.skill;

import daripher.skilltree.skill.bonus.SkillBonus;
import daripher.skilltree.skill.requirement.SkillRequirement;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.List;

public class PassiveSkill {
    private final ResourceLocation id;
    private final List<SkillBonus<?>> bonuses = new ArrayList<>();
    private @Nullable List<SkillRequirement<?>> requirements;
    private @Nullable List<ResourceLocation> directConnections = new ArrayList<>();
    private @Nullable List<ResourceLocation> longConnections = new ArrayList<>();
    private @Nullable List<ResourceLocation> oneWayConnections = new ArrayList<>();
    private @Nullable List<String> tags = new ArrayList<>();
    private ResourceLocation backgroundTexture;
    private ResourceLocation iconTexture;
    private ResourceLocation borderTexture;
    private @Nullable String title;
    private @Nullable String titleColor;
    private float positionX, positionY;
    private int buttonSize;
    private boolean isStartingPoint;
    private boolean isAlwaysStartingPoint;
    private @Nullable List<MutableComponent> description;

    public PassiveSkill(ResourceLocation id, int buttonSize, ResourceLocation backgroundTexture, ResourceLocation iconTexture, ResourceLocation borderTexture, boolean isStartingPoint) {
        this.id = id;
        this.backgroundTexture = backgroundTexture;
        this.iconTexture = iconTexture;
        this.borderTexture = borderTexture;
        this.buttonSize = buttonSize;
        this.isStartingPoint = isStartingPoint;
    }

    public ResourceLocation getId() {
        return id;
    }

    public int getSkillSize() {
        return buttonSize;
    }

    public void setButtonSize(int buttonSize) {
        this.buttonSize = buttonSize;
    }

    public ResourceLocation getFrameTexture() {
        return backgroundTexture;
    }

    public void setBackgroundTexture(ResourceLocation texture) {
        this.backgroundTexture = texture;
    }

    public ResourceLocation getIconTexture() {
        return iconTexture;
    }

    public void setIconTexture(ResourceLocation texture) {
        this.iconTexture = texture;
    }

    public ResourceLocation getTooltipFrameTexture() {
        return borderTexture;
    }

    public void setBorderTexture(ResourceLocation texture) {
        this.borderTexture = texture;
    }

    public boolean isStartingPoint() {
        return isStartingPoint || isAlwaysStartingPoint;
    }

    public void setStartingPoint(boolean isStartingPoint) {
        this.isStartingPoint = isStartingPoint;
    }

    public boolean isAlwaysStartingPoint() {
        return isAlwaysStartingPoint;
    }

    public void setAlwaysStartingPoint(boolean alwaysStartingPoint) {
        isAlwaysStartingPoint = alwaysStartingPoint;
    }

    public List<SkillBonus<?>> getBonuses() {
        return bonuses;
    }

    public @Nonnull List<SkillRequirement<?>> getRequirements() {
        if (requirements == null) {
            return requirements = new ArrayList<>();
        }
        return requirements;
    }

    public void addSkillBonus(SkillBonus<?> bonus) {
        bonuses.add(bonus);
    }

    public void addSkillRequirement(SkillRequirement<?> requirement) {
        getRequirements().add(requirement);
    }

    public void connect(PassiveSkill otherSkill) {
        getDirectConnections().add(otherSkill.getId());
    }

    public void setPosition(float x, float y) {
        positionX = x;
        positionY = y;
    }

    public float getPositionX() {
        return positionX;
    }

    public float getPositionY() {
        return positionY;
    }

    @Nonnull
    public List<ResourceLocation> getDirectConnections() {
        if (directConnections == null) {
            return directConnections = new ArrayList<>();
        }
        return directConnections;
    }

    @Nonnull
    public List<ResourceLocation> getLongConnections() {
        if (longConnections == null) {
            return longConnections = new ArrayList<>();
        }
        return longConnections;
    }

    @Nonnull
    public List<ResourceLocation> getOneWayConnections() {
        if (oneWayConnections == null) {
            return oneWayConnections = new ArrayList<>();
        }
        return oneWayConnections;
    }

    @Nonnull
    public List<String> getTags() {
        if (tags == null) {
            return tags = new ArrayList<>();
        }
        return tags;
    }

    public @Nonnull String getTitle() {
        return title == null ? "" : title;
    }

    public void setTitle(@Nonnull String title) {
        this.title = title.isEmpty() ? null : title;
    }

    public void learn(ServerPlayer player, boolean firstTime) {
        getBonuses().forEach(b -> b.onSkillLearned(player, firstTime));
    }

    public void setTitleColor(@Nullable String color) {
        this.titleColor = color;
    }

    public @Nonnull String getTitleColor() {
        return titleColor == null ? "" : titleColor;
    }

    public @Nullable List<MutableComponent> getDescription() {
        return description;
    }

    public void setDescription(@Nullable List<MutableComponent> description) {
        this.description = description;
    }

    public void remove(ServerPlayer player) {
        getBonuses().forEach(b -> b.onSkillRemoved(player));
    }

    public boolean isInvalid() {
        return getId() == null || getBonuses() == null || getFrameTexture() == null || getIconTexture() == null || getTooltipFrameTexture() == null;
    }
}

package daripher.skilltree.skill.bonus.item;

import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import daripher.skilltree.client.widget.editor.SkillTreeEditor;
import daripher.skilltree.data.reloader.SkillsReloader;
import daripher.skilltree.init.PSTItemBonuses;
import daripher.skilltree.init.PSTRegistries;
import daripher.skilltree.network.NetworkHelper;
import daripher.skilltree.skill.bonus.SkillBonus;
import daripher.skilltree.skill.bonus.player.OutgoingDamageBonus;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;

import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;

public final class EquipmentBonus implements ItemBonus<EquipmentBonus> {
    private SkillBonus<?> skillBonus;

    public EquipmentBonus(SkillBonus<?> skillBonus) {
        this.skillBonus = skillBonus;
    }

    @Override
    public boolean canMerge(ItemBonus<?> other) {
        if (!(other instanceof EquipmentBonus otherBonus)) {
            return false;
        }
        return otherBonus.skillBonus.canMerge(this.skillBonus);
    }

    @Override
    public EquipmentBonus merge(ItemBonus<?> other) {
        if (!(other instanceof EquipmentBonus otherBonus)) {
            throw new IllegalArgumentException();
        }
        return new EquipmentBonus(otherBonus.skillBonus.merge(this.skillBonus));
    }

    @Override
    public EquipmentBonus copy() {
        return new EquipmentBonus(skillBonus.copy());
    }

    @Override
    public EquipmentBonus multiply(double multiplier) {
        skillBonus.multiply(multiplier);
        return this;
    }

    @Override
    public ItemBonus.Serializer getSerializer() {
        return PSTItemBonuses.SKILL_BONUS.get();
    }

    @Override
    public List<MutableComponent> getFullTooltip() {
        return skillBonus.getFullTooltip();
    }

    @Override
    public boolean isPositive() {
        return skillBonus.isPositive();
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj == null || obj.getClass() != this.getClass()) {
            return false;
        }
        EquipmentBonus that = (EquipmentBonus) obj;
        return Objects.equals(this.skillBonus, that.skillBonus);
    }

    @Override
    public void addEditorWidgets(SkillTreeEditor editor, Consumer<EquipmentBonus> consumer) {
        skillBonus.addEditorWidgets(editor, skillBonus -> {
            setSkillBonus(skillBonus);
            consumer.accept(this.copy());
        });
    }

    public SkillBonus<?> getSkillBonus() {
        return skillBonus;
    }

    public void setSkillBonus(SkillBonus<?> skillBonus) {
        this.skillBonus = skillBonus;
    }

    @Override
    public int hashCode() {
        return Objects.hash(skillBonus);
    }

    @Override
    public String toString() {
        return "EquipmentBonus[" + "skillBonus=" + skillBonus + ']';
    }


    public static class Serializer implements ItemBonus.Serializer {
        @Override
        public ItemBonus<?> deserialize(JsonObject json) throws JsonParseException {
            return new EquipmentBonus(SkillsReloader.GSON.fromJson(json.get("skill_bonus"), SkillBonus.class));
        }

        @Override
        public void serialize(JsonObject json, ItemBonus<?> bonus) {
            if (!(bonus instanceof EquipmentBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            JsonObject skillBonusJson = new JsonObject();
            SkillBonus<?> skillBonus = aBonus.skillBonus;
            ResourceLocation serializerId = PSTRegistries.SKILL_BONUSES.get().getKey(skillBonus.getSerializer());
            Objects.requireNonNull(serializerId);
            skillBonusJson.addProperty("type", serializerId.toString());
            skillBonus.getSerializer().serialize(skillBonusJson, skillBonus);
            json.add("skill_bonus", skillBonusJson);
        }

        @Override
        public ItemBonus<?> deserialize(CompoundTag tag) {
            CompoundTag skillBonusTag = tag.getCompound("skill_bonus");
            String type = skillBonusTag.getString("type");
            ResourceLocation serializerId = ResourceLocation.parse(type);
            SkillBonus.Serializer serializer = PSTRegistries.SKILL_BONUSES.get().getValue(serializerId);
            Objects.requireNonNull(serializer, "Unknown skill bonus: " + serializerId);
            SkillBonus<?> skillBonus = serializer.deserialize(skillBonusTag);
            return new EquipmentBonus(skillBonus);
        }

        @Override
        public CompoundTag serialize(ItemBonus<?> bonus) {
            if (!(bonus instanceof EquipmentBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            SkillBonus<?> skillBonus = aBonus.getSkillBonus();
            SkillBonus.Serializer serializer = skillBonus.getSerializer();
            ResourceLocation serializerId = PSTRegistries.SKILL_BONUSES.get().getKey(serializer);
            Objects.requireNonNull(serializerId);
            CompoundTag skillBonusTag = serializer.serialize(skillBonus);
            skillBonusTag.putString("type", serializerId.toString());
            tag.put("skill_bonus", skillBonusTag);
            return tag;
        }

        @Override
        public ItemBonus<?> deserialize(FriendlyByteBuf buf) {
            return new EquipmentBonus(NetworkHelper.readSkillBonus(buf));
        }

        @Override
        public void serialize(FriendlyByteBuf buf, ItemBonus<?> bonus) {
            if (!(bonus instanceof EquipmentBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            NetworkHelper.writeSkillBonus(buf, aBonus.skillBonus);
        }

        @Override
        public ItemBonus<?> createDefaultInstance() {
            return new EquipmentBonus(new OutgoingDamageBonus(0.1f, AttributeModifier.Operation.MULTIPLY_BASE));
        }
    }
}

