import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;

public final class GroupedItemBonus implements ItemBonus<GroupedItemBonus> {
    private final ArrayList<ItemBonus<?>> innerBonuses;

    public GroupedItemBonus(ArrayList<ItemBonus<?>> innerBonuses) {
        this.innerBonuses = innerBonuses;
    }

    @Override
    public boolean canMerge(ItemBonus<?> other) {
        return other instanceof GroupedItemBonus;
    }

    @Override
    public GroupedItemBonus merge(ItemBonus<?> other) {
        if (!(other instanceof GroupedItemBonus otherBonus)) {
            throw new IllegalArgumentException();
        }
        return ItemBonusHandler.mergeGroupedItemBonuses(this, otherBonus);
    }

    @Override
    public GroupedItemBonus copy() {
        return new GroupedItemBonus(new ArrayList<>(innerBonuses.stream().map(ItemBonus::copy).toList()));
    }

    @Override
    public GroupedItemBonus multiply(double multiplier) {
        innerBonuses.forEach(bonus -> bonus.multiply(multiplier));
        return this;
    }

    @Override
    public ItemBonus.Serializer getSerializer() {
        return PSTItemBonuses.ITEM_BONUS_LIST.get();
    }

    @Override
    public List<MutableComponent> getFullTooltip() {
        List<MutableComponent> fullTooltip = new ArrayList<>();
        for (ItemBonus<?> itemBonus : innerBonuses) {
            fullTooltip.addAll(itemBonus.getFullTooltip());
        }
        return fullTooltip;
    }

    @Override
    public boolean isPositive() {
        return innerBonuses.stream().anyMatch(ItemBonus::isPositive);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        GroupedItemBonus that = (GroupedItemBonus) o;
        return Objects.equals(innerBonuses, that.innerBonuses);
    }

    @Override
    public int hashCode() {
        return Objects.hash(innerBonuses);
    }

    @SuppressWarnings({"rawtypes"})
    @Override
    public void addEditorWidgets(SkillTreeEditor editor, Consumer<GroupedItemBonus> consumer) {
        ItemBonus<?> defaultBonus = PSTItemBonuses.SKILL_BONUS.get().createDefaultInstance();
        editor.addSelectionMenu(0, 0, 90, defaultBonus).setResponder(itemBonus -> {
            addItemBonus(editor, itemBonus);
            consumer.accept(this);
        }).setMessage(Component.literal("Add"));
        editor.increaseHeight(29);
        for (int i = 0; i < getInnerBonuses().size(); i++) {
            final int bonusIndex = i;
            ItemBonus selectedItemBonus = getInnerBonuses().get(i);
            MutableComponent tooltip = getFullTooltip().get(0);
            String message = tooltip.getString();
            message = TooltipHelper.getTrimmedString(message, 190);
            editor.addButton(0, 0, 200, 14, message).setPressFunc(button -> {
                ItemBonusEditor itemBonusEditor = new ItemBonusEditor(editor, editor.getSelectedMenu(), bonus -> skillBonusChanged(bonus, bonusIndex, consumer), () -> selectedItemBonus);
                editor.selectMenu(itemBonusEditor);
            });
            editor.increaseHeight(19);
        }
    }

    private void skillBonusChanged(@Nullable ItemBonus<?> itemBonus, int selectedBonusIndex, Consumer<GroupedItemBonus> consumer) {
        if (itemBonus == null) {
            deleteSelectedItemBonuses(selectedBonusIndex);
        } else {
            setItemBonuses(itemBonus, selectedBonusIndex);
        }
        consumer.accept(this.copy());
    }

    private void setItemBonuses(ItemBonus<?> bonus, int selectedBonusIndex) {
        innerBonuses.set(selectedBonusIndex, bonus);
    }

    private void deleteSelectedItemBonuses(int selectedBonusIndex) {
        if (getInnerBonuses().size() > selectedBonusIndex) {
            getInnerBonuses().remove(selectedBonusIndex);
        }
    }

    @SuppressWarnings("rawtypes")
    private void addItemBonus(SkillTreeEditor editor, ItemBonus<?> itemBonus) {
        final EditorMenu previousMenu = editor.getSelectedMenu().previousMenu;
        if (itemBonus instanceof EquipmentBonus equipmentBonus) {
            SelectionList<SkillBonus> skillBonusSelectionList = new TextSelectionList<>(0, 0, 190, 14, PSTSkillBonuses.defaultInstances()).setRows(8)
                    .setNameGetter(bonus -> Component.literal(PSTSkillBonuses.getName(bonus)))
                    .selectElement(equipmentBonus.getSkillBonus());
            editor.selectMenu(new SelectionMenu<>(editor, editor.getSelectedMenu(), skillBonusSelectionList, () -> {
            }).setResponder(skillBonus -> {
                innerBonuses.add(new EquipmentBonus(skillBonus));
                editor.selectMenu(previousMenu);
            }));
            return;
        }
        innerBonuses.add(itemBonus);
        editor.selectMenu(previousMenu);
    }

    public List<? extends ItemBonus<?>> getInnerBonuses() {
        return innerBonuses;
    }

    @Override
    public String toString() {
        return "GroupedItemBonus[" + "innerBonuses=" + innerBonuses + ']';
    }


    public static class Serializer implements ItemBonus.Serializer {
        @Override
        public ItemBonus<?> deserialize(JsonObject json) throws JsonParseException {
            JsonArray innerBonusesJson = json.get("inner_bonuses").getAsJsonArray();
            ArrayList<ItemBonus<?>> innerBonuses = new ArrayList<>();
            for (int i = 0; i < innerBonusesJson.size(); i++) {
                JsonObject innerBonusTag = innerBonusesJson.get(i).getAsJsonObject();
                String serializerIdString = innerBonusTag.get("type").getAsString();
                ResourceLocation serializerId = ResourceLocation.parse(serializerIdString);
                ItemBonus.Serializer serializer = PSTRegistries.ITEM_BONUSES.get().getValue(serializerId);
                Objects.requireNonNull(serializer, "Unknown item bonus: " + serializerId);
                ItemBonus<?> innerBonus = serializer.deserialize(innerBonusTag);
                innerBonuses.add(innerBonus);
            }
            return new GroupedItemBonus(innerBonuses);
        }

        @Override
        public void serialize(JsonObject json, ItemBonus<?> bonus) {
            if (!(bonus instanceof GroupedItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            JsonArray innerBonusesJson = new JsonArray();
            for (int i = 0; i < aBonus.innerBonuses.size(); i++) {
                ItemBonus<?> innerBonus = aBonus.innerBonuses.get(i);
                ItemBonus.Serializer serializer = innerBonus.getSerializer();
                ResourceLocation serializerId = PSTRegistries.ITEM_BONUSES.get().getKey(serializer);
                Objects.requireNonNull(serializerId);
                JsonObject innerBonusJson = new JsonObject();
                innerBonusJson.addProperty("type", serializerId.toString());
                serializer.serialize(innerBonusJson, innerBonus);
                innerBonusesJson.add(innerBonusJson);
            }
            json.add("inner_bonuses", innerBonusesJson);
        }

        @Override
        public ItemBonus<?> deserialize(CompoundTag tag) {
            ArrayList<ItemBonus<?>> innerBonuses = new ArrayList<>();
            ListTag innerBonusesTag = tag.getList("inner_bonuses", Tag.TAG_COMPOUND);
            for (Tag value : innerBonusesTag) {
                CompoundTag innerBonusTag = (CompoundTag) value;
                String type = innerBonusTag.getString("type");
                ResourceLocation serializerId = ResourceLocation.parse(type);
                ItemBonus.Serializer serializer = PSTRegistries.ITEM_BONUSES.get().getValue(serializerId);
                Objects.requireNonNull(serializer, "Unknown item bonus: " + serializerId);
                innerBonuses.add(serializer.deserialize(innerBonusTag));
            }
            return new GroupedItemBonus(innerBonuses);
        }

        @Override
        public CompoundTag serialize(ItemBonus<?> bonus) {
            if (!(bonus instanceof GroupedItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            ListTag innerBonusesTag = new ListTag();
            for (int i = 0; i < aBonus.innerBonuses.size(); i++) {
                ItemBonus<?> innerBonus = aBonus.innerBonuses.get(i);
                ItemBonus.Serializer serializer = innerBonus.getSerializer();
                ResourceLocation serializerId = PSTRegistries.ITEM_BONUSES.get().getKey(serializer);
                Objects.requireNonNull(serializerId);
                CompoundTag innerBonusTag = serializer.serialize(innerBonus);
                innerBonusTag.putString("type", serializerId.toString());
                innerBonusesTag.add(innerBonusTag);
            }
            tag.put("inner_bonuses", innerBonusesTag);
            return tag;
        }

        @Override
        public ItemBonus<?> deserialize(FriendlyByteBuf buf) {
            ArrayList<ItemBonus<?>> innerBonuses = new ArrayList<>();
            int size = buf.readInt();
            for (int i = 0; i < size; i++) {
                innerBonuses.add(NetworkHelper.readItemBonus(buf));
            }
            return new GroupedItemBonus(innerBonuses);
        }

        @Override
        public void serialize(FriendlyByteBuf buf, ItemBonus<?> bonus) {
            if (!(bonus instanceof GroupedItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            buf.writeInt(aBonus.innerBonuses.size());
            for (int i = 0; i < aBonus.innerBonuses.size(); i++) {
                NetworkHelper.writeItemBonus(buf, aBonus.innerBonuses.get(i));
            }
        }

        @Override
        public ItemBonus<?> createDefaultInstance() {
            AttributeModifier defaultModifier = new AttributeModifier("Default Modifier", 1, AttributeModifier.Operation.ADDITION);
            ItemBonus<?> bonus1 = new EquipmentBonus(new AttributeBonus(Attributes.ARMOR, defaultModifier));
            ItemBonus<?> bonus2 = new EquipmentBonus(new AttributeBonus(Attributes.ARMOR_TOUGHNESS, defaultModifier));
            ArrayList<ItemBonus<?>> bonuses = new ArrayList<>();
            bonuses.add(bonus1);
            bonuses.add(bonus2);
            return new GroupedItemBonus(bonuses);
        }
    }
}

package daripher.skilltree.skill.bonus.item;

import com.google.common.collect.ImmutableList;
import daripher.skilltree.SkillTreeMod;
import daripher.skilltree.client.tooltip.TooltipHelper;
import daripher.skilltree.init.PSTRegistries;
import daripher.skilltree.skill.SkillBonusProvider;
import daripher.skilltree.skill.bonus.player.AttributeBonus;
import daripher.skilltree.skill.bonus.player.ItemUpgradeLimitBonusesBonus;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.event.entity.living.LivingEquipmentChangeEvent;
import net.minecraftforge.event.entity.player.ItemTooltipEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

@Mod.EventBusSubscriber(modid = SkillTreeMod.MOD_ID, bus = Mod.EventBusSubscriber.Bus.FORGE)
public class ItemBonusHandler {
    public static final String UPGRADE_BONUSES_TAG_NAME = "UpgradeBonuses";
    public static final String CRAFTING_BONUSES_TAG_NAME = "CraftingBonuses";

    @SubscribeEvent
    public static void addItemBonusTooltips(ItemTooltipEvent event) {
        List<Component> toolTip = event.getToolTip();
        List<ItemBonus<?>> itemBonuses = getItemBonuses(event.getItemStack(), ItemBonus.class);
        if (itemBonuses.isEmpty()) {
            return;
        }
        toolTip.add(Component.empty());
        List<ItemBonus<?>> mergedItemBonuses = mergeItemBonuses(itemBonuses);
        for (ItemBonus<?> itemBonus : mergedItemBonuses) {
            Style style = TooltipHelper.getItemUpgradeStyle();
            for (MutableComponent mutableComponent : itemBonus.getFullTooltip()) {
                toolTip.add(mutableComponent.withStyle(style));
            }
        }
    }

    @SubscribeEvent
    public static void addEquipmentAttributeBonuses(LivingEquipmentChangeEvent event) {
        LivingEntity entity = event.getEntity();
        if (!(entity instanceof Player)) {
            return;
        }
        for (ItemBonus<?> itemBonus : getItemBonuses(event.getFrom(), EquipmentBonus.class)) {
            EquipmentBonus bonus = (EquipmentBonus) itemBonus;
            if (!(bonus.getSkillBonus() instanceof AttributeBonus attributeBonus)) {
                continue;
            }
            AttributeInstance attributeInstance = entity.getAttribute(attributeBonus.getAttribute());
            if (attributeInstance == null) {
                continue;
            }
            attributeInstance.removeModifier(attributeBonus.getModifier().getId());
        }
        for (ItemBonus<?> itemBonus : getItemBonuses(event.getTo(), EquipmentBonus.class)) {
            EquipmentBonus bonus = (EquipmentBonus) itemBonus;
            if (!(bonus.getSkillBonus() instanceof AttributeBonus attributeBonus)) {
                continue;
            }
            if (attributeBonus.isDynamic()) {
                continue;
            }
            AttributeInstance attributeInstance = entity.getAttribute(attributeBonus.getAttribute());
            if (attributeInstance == null) {
                continue;
            }
            if (attributeInstance.hasModifier(attributeBonus.getModifier())) {
                continue;
            }
            attributeInstance.addTransientModifier(attributeBonus.getModifier());
        }
    }

    public static void addCraftingBonuses(ItemStack itemStack, GroupedItemBonus itemBonuses) {
        List<ItemBonus<?>> craftingBonuses = getBonusesFromTag(itemStack, CRAFTING_BONUSES_TAG_NAME);
        craftingBonuses.add(itemBonuses);
        setCraftingBonuses(itemStack, craftingBonuses);
    }

    public static List<ItemBonus<?>> getItemBonuses(ItemStack itemStack) {
        if (!itemStack.hasTag()) {
            return ImmutableList.of();
        }
        List<ItemBonus<?>> list = new ArrayList<>();
        list.addAll(getUpgradeBonuses(itemStack));
        list.addAll(getCraftingBonuses(itemStack));
        return list;
    }

    private static List<ItemBonus<?>> getCraftingBonuses(ItemStack itemStack) {
        return getBonusesFromTag(itemStack, CRAFTING_BONUSES_TAG_NAME);
    }

    private static List<ItemBonus<?>> getUpgradeBonuses(ItemStack itemStack) {
        return getBonusesFromTag(itemStack, UPGRADE_BONUSES_TAG_NAME);
    }

    private static List<ItemBonus<?>> getBonusesFromTag(ItemStack itemStack, String subTagName) {
        CompoundTag stackTag = itemStack.getOrCreateTag();
        List<ItemBonus<?>> itemBonuses = new ArrayList<>();
        if (!stackTag.contains(subTagName, Tag.TAG_LIST)) {
            return new ArrayList<>();
        }
        ListTag bonusesTagList = stackTag.getList(subTagName, Tag.TAG_COMPOUND);
        bonusesTagList.stream().map(CompoundTag.class::cast).forEach(bonusTag -> itemBonuses.add(deserializeBonus(bonusTag)));
        return itemBonuses;
    }

    public static List<ItemBonus<?>> getItemBonuses(ItemStack stack, Class<?> type) {
        List<ItemBonus<?>> bonuses = new ArrayList<>();
        for (ItemBonus<?> bonus : getItemBonuses(stack)) {
            if (bonus instanceof GroupedItemBonus listBonus) {
                bonuses.addAll(getItemBonuses(listBonus));
            } else {
                bonuses.add(bonus);
            }
        }
        return bonuses.stream().filter(type::isInstance).toList();
    }

    private static List<? extends ItemBonus<?>> getItemBonuses(GroupedItemBonus listBonus) {
        List<ItemBonus<?>> bonuses = new ArrayList<>();
        for (ItemBonus<?> bonus : listBonus.getInnerBonuses()) {
            if (bonus instanceof GroupedItemBonus innerListBonus) {
                List<? extends ItemBonus<?>> innerBonuses = getItemBonuses(innerListBonus);
                bonuses.addAll(innerBonuses);
            } else {
                bonuses.add(bonus);
            }
        }
        return bonuses;
    }

    public static void setUpgradeBonuses(ItemStack stack, List<ItemBonus<?>> bonuses) {
        setTagBonuses(stack, bonuses, UPGRADE_BONUSES_TAG_NAME);
    }

    public static void setCraftingBonuses(ItemStack stack, List<ItemBonus<?>> bonuses) {
        setTagBonuses(stack, bonuses, CRAFTING_BONUSES_TAG_NAME);
    }

    private static void setTagBonuses(ItemStack stack, List<ItemBonus<?>> bonuses, String tagName) {
        ListTag bonusesTagList = new ListTag();
        for (ItemBonus<?> itemBonus : bonuses) {
            bonusesTagList.add(serializeBonus(itemBonus));
        }
        stack.getOrCreateTag().put(tagName, bonusesTagList);
    }

    private static CompoundTag serializeBonus(ItemBonus<? extends ItemBonus<?>> bonus) {
        ItemBonus.Serializer serializer = bonus.getSerializer();
        CompoundTag bonusTag = serializer.serialize(bonus);
        ResourceLocation id = PSTRegistries.ITEM_BONUSES.get().getKey(serializer);
        bonusTag.putString("type", Objects.requireNonNull(id).toString());
        return bonusTag;
    }

    private static ItemBonus<?> deserializeBonus(CompoundTag tag) {
        if (!tag.contains("type")) {
            return null;
        }
        ResourceLocation id = ResourceLocation.parse(tag.getString("type"));
        ItemBonus.Serializer serializer = PSTRegistries.ITEM_BONUSES.get().getValue(id);
        if (serializer == null) {
            return null;
        }
        try {
            return serializer.deserialize(tag);
        } catch (Exception exception) {
            String errorMessage = "Couldn't deserialize item bonus from " + tag;
            SkillTreeMod.LOGGER.error(errorMessage, exception);
            return null;
        }
    }

    public static int getCraftedBonusLimit(ItemStack itemStack, @Nullable Player player) {
        int limit = 1;
        if (player != null) {
            limit += SkillBonusProvider.getSkillBonuses(player, ItemUpgradeLimitBonusesBonus.class).stream()
                    .filter(bonus -> bonus.getItemCondition().test(itemStack)).map(ItemUpgradeLimitBonusesBonus::getAmount)
                    .reduce(Integer::sum).orElse(0);
        }
        return limit;
    }

    @NotNull
    @SuppressWarnings({"rawtypes", "unchecked", "SuspiciousMethodCalls"})
    public static <T> List<T> mergeItemBonuses(List<T> bonuses) {
        List<T> mergedBonuses = new ArrayList<>();
        for (T bonus : bonuses) {
            ItemBonus itemBonus = (ItemBonus) bonus;
            Optional<ItemBonus> mergeTarget = mergedBonuses.stream().map(ItemBonus.class::cast).filter(itemBonus::canMerge).findAny();
            if (mergeTarget.isPresent()) {
                mergedBonuses.remove(mergeTarget.get());
                mergedBonuses.add((T) mergeTarget.get().copy().merge(itemBonus));
            } else {
                mergedBonuses.add((T) itemBonus);
            }
        }
        return mergedBonuses;
    }

    public static GroupedItemBonus mergeGroupedItemBonuses(GroupedItemBonus itemBonus1, GroupedItemBonus itemBonus2) {
        ArrayList<ItemBonus<?>> innerBonuses = new ArrayList<>();
        innerBonuses.addAll(itemBonus1.getInnerBonuses());
        innerBonuses.addAll(itemBonus2.getInnerBonuses());
        ItemBonusHandler.mergeItemBonuses(innerBonuses);
        return new GroupedItemBonus(innerBonuses);
    }
}

package daripher.skilltree.skill.bonus.player;

import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import daripher.skilltree.SkillTreeMod;
import daripher.skilltree.client.tooltip.TooltipHelper;
import daripher.skilltree.client.widget.editor.SkillTreeEditor;
import daripher.skilltree.data.serializers.SerializationHelper;
import daripher.skilltree.init.PSTSkillBonuses;
import daripher.skilltree.network.NetworkHelper;
import daripher.skilltree.skill.bonus.SkillBonus;
import daripher.skilltree.skill.bonus.TickingSkillBonus;
import daripher.skilltree.skill.bonus.function.AttributeValueFunction;
import daripher.skilltree.skill.bonus.multiplier.FloatFunctionMultiplier;
import daripher.skilltree.skill.bonus.multiplier.LivingMultiplier;
import daripher.skilltree.skill.bonus.multiplier.NoneLivingMultiplier;
import daripher.skilltree.skill.bonus.predicate.living.LivingEntityPredicate;
import daripher.skilltree.skill.bonus.predicate.living.NoneLivingEntityPredicate;
import net.minecraft.ChatFormatting;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.player.Player;

import javax.annotation.Nonnull;
import java.util.Objects;
import java.util.UUID;
import java.util.function.Consumer;

public final class AttributeBonus implements SkillBonus<AttributeBonus>, TickingSkillBonus {
    private Attribute attribute;
    private AttributeModifier modifier;
    private @Nonnull LivingMultiplier playerMultiplier = NoneLivingMultiplier.INSTANCE;
    private @Nonnull LivingEntityPredicate playerCondition = NoneLivingEntityPredicate.INSTANCE;

    public AttributeBonus(Attribute attribute, AttributeModifier modifier) {
        this.attribute = attribute;
        this.modifier = modifier;
    }

    @Override
    public void onSkillLearned(ServerPlayer player, boolean firstTime) {
        if (playerCondition != NoneLivingEntityPredicate.INSTANCE || playerMultiplier != NoneLivingMultiplier.INSTANCE) {
            return;
        }
        AttributeInstance instance = player.getAttribute(attribute);
        if (instance == null) {
            SkillTreeMod.LOGGER.error("Attempting to add attribute modifier to attribute {}, which is not present for player", attribute);
            return;
        }
        if (!instance.hasModifier(modifier)) {
            applyAttributeModifier(instance, modifier, player);
        }
    }

    @Override
    public void onSkillRemoved(ServerPlayer player) {
        AttributeInstance instance = player.getAttribute(attribute);
        if (instance == null) {
            SkillTreeMod.LOGGER.error("Attempting to remove attribute modifier from attribute {}, which is not present for player", attribute);
            return;
        }
        instance.removeModifier(modifier.getId());
    }

    @Override
    public void tick(ServerPlayer player) {
        if (!isDynamic()) {
            return;
        }
        if (playerCondition != NoneLivingEntityPredicate.INSTANCE) {
            if (!playerCondition.test(player)) {
                onSkillRemoved(player);
                return;
            }
        }
        if (playerMultiplier != NoneLivingMultiplier.INSTANCE && playerMultiplier.getValue(player) == 0) {
            onSkillRemoved(player);
            return;
        }
        applyDynamicAttributeBonus(player);
    }

    public boolean isDynamic() {
        return playerCondition != NoneLivingEntityPredicate.INSTANCE || playerMultiplier != NoneLivingMultiplier.INSTANCE;
    }

    private void applyDynamicAttributeBonus(ServerPlayer player) {
        AttributeInstance instance = player.getAttribute(attribute);
        if (instance == null) {
            return;
        }
        AttributeModifier oldModifier = instance.getModifier(modifier.getId());
        double value = modifier.getAmount();
        value *= playerMultiplier.getValue(player);
        if (oldModifier != null) {
            if (oldModifier.getAmount() == value) {
                return;
            }
        }
        AttributeModifier dynamicModifier = new AttributeModifier(modifier.getId(), "DynamicBonus", value, modifier.getOperation());
        applyAttributeModifier(instance, dynamicModifier, player);
    }

    private void applyAttributeModifier(AttributeInstance instance, AttributeModifier modifier, Player player) {
        float healthPercentage = player.getHealth() / player.getMaxHealth();
        if (instance.getModifier(modifier.getId()) != null) {
            instance.removeModifier(modifier.getId());
        }
        instance.addTransientModifier(modifier);
        if (attribute == Attributes.MAX_HEALTH) {
            player.setHealth(player.getMaxHealth() * healthPercentage);
        }
    }

    @Override
    public SkillBonus.Serializer getSerializer() {
        return PSTSkillBonuses.ATTRIBUTE.get();
    }

    @Override
    public AttributeBonus copy() {
        AttributeModifier modifier = new AttributeModifier(UUID.randomUUID(), this.modifier.getName(), this.modifier.getAmount(), this.modifier.getOperation());
        AttributeBonus bonus = new AttributeBonus(attribute, modifier);
        bonus.playerMultiplier = this.playerMultiplier;
        bonus.playerCondition = this.playerCondition;
        return bonus;
    }

    @Override
    public AttributeBonus multiply(double multiplier) {
        modifier = new AttributeModifier(modifier.getId(), modifier.getName(), modifier.getAmount() * multiplier, modifier.getOperation());
        return this;
    }

    @Override
    public boolean canMerge(SkillBonus<?> other) {
        if (!(other instanceof AttributeBonus otherBonus)) {
            return false;
        }
        if (otherBonus.attribute != this.attribute) {
            return false;
        }
        if (!Objects.equals(otherBonus.playerMultiplier, this.playerMultiplier)) {
            return false;
        }
        if (!Objects.equals(otherBonus.playerCondition, this.playerCondition)) {
            return false;
        }
        return otherBonus.modifier.getOperation() == this.modifier.getOperation();
    }

    @Override
    public SkillBonus<AttributeBonus> merge(SkillBonus<?> other) {
        if (!(other instanceof AttributeBonus otherBonus)) {
            throw new IllegalArgumentException();
        }
        AttributeModifier mergedModifier = new AttributeModifier(this.modifier.getId(), "Merged", this.modifier.getAmount() + otherBonus.modifier.getAmount(), this.modifier.getOperation());
        AttributeBonus mergedBonus = new AttributeBonus(this.attribute, mergedModifier);
        mergedBonus.playerMultiplier = this.playerMultiplier;
        mergedBonus.playerCondition = this.playerCondition;
        return mergedBonus;
    }

    @Override
    public MutableComponent getSimpleTooltip() {
        float visibleAmount = (float) modifier.getAmount();
        String descriptionId = attribute.getDescriptionId();
        MutableComponent tooltip;
        if (isPercentageRegeneration()) {
            visibleAmount *= 100;
            String amountDescription = TooltipHelper.formatNumber(visibleAmount);
            descriptionId = getDescriptionId() + ".percentage_regeneration";
            tooltip = Component.translatable(descriptionId, amountDescription);
        } else {
            if (isKnockbackResistanceAddition()) {
                visibleAmount *= 10;
            }
            AttributeModifier.Operation operation = modifier.getOperation();
            tooltip = TooltipHelper.getSkillBonusTooltip(descriptionId, visibleAmount, operation);
            tooltip = playerMultiplier.getTooltip(tooltip, Target.PLAYER);
        }
        tooltip = playerCondition.getTooltip(tooltip, Target.PLAYER);
        return tooltip.withStyle(TooltipHelper.getSkillBonusStyle(isPositive()));
    }

    private boolean isKnockbackResistanceAddition() {
        return modifier.getOperation() == AttributeModifier.Operation.ADDITION && attribute.equals(Attributes.KNOCKBACK_RESISTANCE);
    }

    private boolean isPercentageRegeneration() {
        return modifier.getOperation() == AttributeModifier.Operation.ADDITION && playerMultiplier instanceof FloatFunctionMultiplier floatFunctionMultiplier && floatFunctionMultiplier.getFloatFunction() instanceof AttributeValueFunction attributeValueFunction && attributeValueFunction.getAttribute() == Attributes.MAX_HEALTH && floatFunctionMultiplier.getDivisor() == 1;
    }

    @Override
    public void gatherInfo(Consumer<MutableComponent> consumer) {
        SkillBonus.super.gatherInfo(consumer);
        TooltipHelper.consumeTranslated(attribute.getDescriptionId() + ".info", consumer);
    }

    @Override
    public boolean isPositive() {
        return modifier.getAmount() > 0;
    }

    @Override
    public void addEditorWidgets(SkillTreeEditor editor, Consumer<AttributeBonus> consumer) {
        editor.addLabel(0, 0, "Attribute", ChatFormatting.GOLD);
