package daripher.skilltree.skill.bonus.player;

import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import daripher.skilltree.client.tooltip.TooltipHelper;
import daripher.skilltree.client.widget.editor.SkillTreeEditor;
import daripher.skilltree.data.serializers.SerializationHelper;
import daripher.skilltree.init.PSTSkillBonuses;
import daripher.skilltree.network.NetworkHelper;
import daripher.skilltree.skill.bonus.SkillBonus;
import daripher.skilltree.skill.bonus.item.EquipmentBonus;
import daripher.skilltree.skill.bonus.item.GroupedItemBonus;
import daripher.skilltree.skill.bonus.item.ItemBonus;
import daripher.skilltree.skill.bonus.item.ItemBonusHandler;
import daripher.skilltree.skill.bonus.predicate.item.EquipmentPredicate;
import daripher.skilltree.skill.bonus.predicate.item.ItemStackPredicate;
import net.minecraft.ChatFormatting;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.world.item.ItemStack;

import javax.annotation.Nonnull;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;

public final class CraftedItemBonusBonus implements SkillBonus<CraftedItemBonusBonus> {
    private @Nonnull ItemStackPredicate itemStackPredicate;
    private @Nonnull GroupedItemBonus itemBonuses;

    public CraftedItemBonusBonus(@Nonnull ItemStackPredicate itemStackPredicate, @Nonnull GroupedItemBonus itemBonuses) {
        this.itemStackPredicate = itemStackPredicate;
        this.itemBonuses = itemBonuses;
    }

    public void itemCrafted(ItemStack craftResult) {
        if (!itemStackPredicate.test(craftResult)) {
            return;
        }
        ItemBonusHandler.addCraftingBonuses(craftResult, itemBonuses);
    }

    @Override
    public SkillBonus.Serializer getSerializer() {
        return PSTSkillBonuses.CRAFTED_ITEM_BONUS.get();
    }

    @Override
    public CraftedItemBonusBonus copy() {
        return new CraftedItemBonusBonus(itemStackPredicate, itemBonuses);
    }

    @Override
    public CraftedItemBonusBonus multiply(double multiplier) {
        return this;
    }

    @Override
    public boolean canMerge(SkillBonus<?> other) {
        if (!(other instanceof CraftedItemBonusBonus otherBonus)) {
            return false;
        }
        return Objects.equals(otherBonus.itemStackPredicate, this.itemStackPredicate);
    }

    @Override
    public SkillBonus<CraftedItemBonusBonus> merge(SkillBonus<?> other) {
        if (!(other instanceof CraftedItemBonusBonus otherBonus)) {
            throw new IllegalArgumentException();
        }
        GroupedItemBonus mergedItemBonuses = ItemBonusHandler.mergeGroupedItemBonuses(itemBonuses, otherBonus.itemBonuses);
        return new CraftedItemBonusBonus(itemStackPredicate, mergedItemBonuses);
    }

    @Override
    public MutableComponent getSimpleTooltip() {
        Style tooltipStyle = TooltipHelper.getSkillBonusStyle(isPositive());
        Component itemDescription = itemStackPredicate.getTooltip("plural");
        return Component.translatable(getDescriptionId(), itemDescription).withStyle(tooltipStyle);
    }

    @Override
    public List<MutableComponent> getFullTooltip() {
        List<MutableComponent> fullTooltip = new ArrayList<>();
        fullTooltip.add(getSimpleTooltip());
        for (MutableComponent mutableComponent : itemBonuses.getFullTooltip()) {
            MutableComponent listItemPrefix = Component.translatable(getDescriptionId() + ".list_item_prefix");
            fullTooltip.add(listItemPrefix.append(mutableComponent).withStyle(mutableComponent.getStyle()));
        }
        return fullTooltip;
    }

    @Override
    public boolean isPositive() {
        return true;
    }

    @Override
    public void addEditorWidgets(SkillTreeEditor editor, Consumer<CraftedItemBonusBonus> consumer) {
        editor.addLabel(0, 0, "Item Condition", ChatFormatting.GOLD);
        editor.increaseHeight(19);
        editor.addSelectionMenu(0, 0, 200, itemStackPredicate).setResponder(condition -> selectItemCondition(editor, consumer, condition))
                .setMenuInitFunc(() -> addItemConditionWidgets(editor, consumer));
        editor.increaseHeight(19);
        editor.addLabel(0, 0, "Item Bonuses", ChatFormatting.GOLD);
        editor.increaseHeight(19);
        addItemBonusWidgets(editor, consumer);
    }

    private void addItemBonusWidgets(SkillTreeEditor editor, Consumer<CraftedItemBonusBonus> consumer) {
        itemBonuses.addEditorWidgets(editor, itemBonuses -> {
            selectItemBonuses(consumer, itemBonuses);
            consumer.accept(this.copy());
        });
    }

    private void selectItemBonuses(Consumer<CraftedItemBonusBonus> consumer, GroupedItemBonus itemBonuses) {
        setItemBonuses(itemBonuses);
        consumer.accept(this.copy());
    }

    private void setItemBonuses(@Nonnull GroupedItemBonus itemBonuses) {
        this.itemBonuses = itemBonuses;
    }

    private void selectItemCondition(SkillTreeEditor editor, Consumer<CraftedItemBonusBonus> consumer, ItemStackPredicate condition) {
        setItemCondition(condition);
        consumer.accept(this.copy());
        editor.rebuildWidgets();
    }

    private void addItemConditionWidgets(SkillTreeEditor editor, Consumer<CraftedItemBonusBonus> consumer) {
        itemStackPredicate.addEditorWidgets(editor, c -> {
            setItemCondition(c);
            consumer.accept(this.copy());
        });
    }

    public void setItemCondition(@Nonnull ItemStackPredicate itemStackPredicate) {
        this.itemStackPredicate = itemStackPredicate;
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj == null || obj.getClass() != this.getClass()) {
            return false;
        }
        CraftedItemBonusBonus that = (CraftedItemBonusBonus) obj;
        return Objects.equals(this.itemStackPredicate, that.itemStackPredicate);
    }

    @Override
    public int hashCode() {
        return Objects.hash(itemStackPredicate);
    }

    public static class Serializer implements SkillBonus.Serializer {
        @Override
        public CraftedItemBonusBonus deserialize(JsonObject json) throws JsonParseException {
            ItemStackPredicate condition = SerializationHelper.deserializeItemPredicate(json);
            ItemBonus<?> itemBonus = SerializationHelper.deserializeItemBonus(json);
            if (!(itemBonus instanceof GroupedItemBonus itemBonuses)) {
                throw new IllegalArgumentException();
            }
            return new CraftedItemBonusBonus(condition, itemBonuses);
        }

        @Override
        public void serialize(JsonObject json, SkillBonus<?> bonus) {
            if (!(bonus instanceof CraftedItemBonusBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            SerializationHelper.serializeItemPredicate(json, aBonus.itemStackPredicate);
            SerializationHelper.serializeItemBonus(json, aBonus.itemBonuses);
        }

        @Override
        public CraftedItemBonusBonus deserialize(CompoundTag tag) {
            ItemStackPredicate condition = SerializationHelper.deserializeItemPredicate(tag);
            ItemBonus<?> itemBonus = SerializationHelper.deserializeItemBonus(tag);
            if (!(itemBonus instanceof GroupedItemBonus itemBonuses)) {
                throw new IllegalArgumentException();
            }
            return new CraftedItemBonusBonus(condition, itemBonuses);
        }

        @Override
        public CompoundTag serialize(SkillBonus<?> bonus) {
            if (!(bonus instanceof CraftedItemBonusBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            SerializationHelper.serializeItemPredicate(tag, aBonus.itemStackPredicate);
            SerializationHelper.serializeItemBonus(tag, aBonus.itemBonuses);
            return tag;
        }

        @Override
        public CraftedItemBonusBonus deserialize(FriendlyByteBuf buf) {
            ItemStackPredicate itemStackPredicate = NetworkHelper.readItemPredicate(buf);
            ItemBonus<?> itemBonus = NetworkHelper.readItemBonus(buf);
            if (!(itemBonus instanceof GroupedItemBonus itemBonuses)) {
                throw new IllegalArgumentException();
            }
            return new CraftedItemBonusBonus(itemStackPredicate, itemBonuses);
        }

        @Override
        public void serialize(FriendlyByteBuf buf, SkillBonus<?> bonus) {
            if (!(bonus instanceof CraftedItemBonusBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            NetworkHelper.writeItemPredicate(buf, aBonus.itemStackPredicate);
            NetworkHelper.writeItemBonus(buf, aBonus.itemBonuses);
        }

        @Override
        public SkillBonus<?> createDefaultInstance() {
            EquipmentPredicate itemStackPredicate = new EquipmentPredicate(EquipmentPredicate.Type.BOW);
            ItemBonus<?> itemBonus = new EquipmentBonus(new CritChanceBonus(0.05f));
            ArrayList<ItemBonus<?>> itemBonusList = new ArrayList<>();
            itemBonusList.add(itemBonus);
            GroupedItemBonus itemBonuses = new GroupedItemBonus(itemBonusList);
            return new CraftedItemBonusBonus(itemStackPredicate, itemBonuses);
        }
    }
}

package daripher.skilltree.skill.bonus.player;

import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import daripher.skilltree.data.client.SkillTreeEditorData;
import daripher.skilltree.client.tooltip.TooltipHelper;
import daripher.skilltree.client.widget.editor.SkillTreeEditor;
import daripher.skilltree.data.serializers.SerializationHelper;
import daripher.skilltree.init.PSTSkillBonuses;
import daripher.skilltree.skill.bonus.SkillBonus;
import net.minecraft.ChatFormatting;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraftforge.registries.ForgeRegistries;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Consumer;

public final class GrantItemBonus implements SkillBonus<GrantItemBonus> {
    private ResourceLocation itemId;
    private int amount;

    public GrantItemBonus(ResourceLocation itemId, int amount) {
        this.itemId = itemId;
        this.amount = amount;
    }

    @Override
    public void onSkillLearned(ServerPlayer player, boolean firstTime) {
        if (firstTime) {
            Item item = ForgeRegistries.ITEMS.getValue(itemId);
            if (item == null) {
                SkillTreeEditorData.sendChatMessage("Unknown item: " + itemId, ChatFormatting.DARK_RED);
                return;
            }
            int amountLeft = amount;
            while (amountLeft > 64) {
                amountLeft -= 64;
                player.addItem(new ItemStack(item, 64));
            }
            if (amountLeft > 0) {
                player.addItem(new ItemStack(item, amountLeft));
            }
        }
    }

    @Override
    public SkillBonus.Serializer getSerializer() {
        return PSTSkillBonuses.GRANT_ITEM.get();
    }

    @Override
    public GrantItemBonus copy() {
        return new GrantItemBonus(itemId, amount);
    }

    @Override
    public GrantItemBonus multiply(double multiplier) {
        amount = (int) (amount * multiplier);
        return this;
    }

    @Override
    public boolean canMerge(SkillBonus<?> other) {
        if (!(other instanceof GrantItemBonus otherBonus)) {
            return false;
        }
        return Objects.equals(otherBonus.itemId, this.itemId);
    }

    @Override
    public GrantItemBonus merge(SkillBonus<?> other) {
        if (!(other instanceof GrantItemBonus otherBonus)) {
            throw new IllegalArgumentException();
        }
        return new GrantItemBonus(itemId, amount + otherBonus.amount);
    }

    @Override
    public MutableComponent getSimpleTooltip() {
        Item item = ForgeRegistries.ITEMS.getValue(itemId);
        if (item == null) {
            return Component.literal("Unknown item: " + itemId).withStyle(ChatFormatting.DARK_RED);
        }
        Style style = TooltipHelper.getSkillBonusStyle(isPositive());
        Component itemDescription = item.getDescription();
        if (amount > 1) {
            String amountDescription = TooltipHelper.formatNumber(amount);
            return Component.translatable(getDescriptionId() + ".amount", amountDescription, itemDescription).withStyle(style);
        } else {
            return Component.translatable(getDescriptionId(), itemDescription).withStyle(style);
        }
    }

    @Override
    public boolean isPositive() {
        return true;
    }

    @Override
    public void addEditorWidgets(SkillTreeEditor editor, Consumer<GrantItemBonus> consumer) {
        editor.addLabel(0, 0, "Amount", ChatFormatting.GOLD);
        editor.increaseHeight(19);
        editor.addNumericTextField(0, 0, 90, 14, amount).setNumericFilter(v -> v > 0 && v % 1 == 0)
                .setNumericResponder(value -> selectAmount(consumer, value));
        editor.increaseHeight(19);
        editor.addLabel(0, 0, "Item", ChatFormatting.GOLD);
        editor.increaseHeight(19);
        List<ResourceLocation> items = ForgeRegistries.ITEMS.getEntries().stream().map(Map.Entry::getKey).map(ResourceKey::location)
                .toList();
        editor.addSelectionMenu(0, 0, 200, items).setValue(itemId).setElementNameGetter(id -> Component.literal(id.toString()))
                .setResponder(id -> selectItemId(id, consumer));
        editor.increaseHeight(19);
    }

    private void selectItemId(ResourceLocation id, Consumer<GrantItemBonus> consumer) {
        setItemId(id);
        consumer.accept(this.copy());
    }

    public void setItemId(ResourceLocation itemId) {
        this.itemId = itemId;
    }

    private void selectAmount(Consumer<GrantItemBonus> consumer, Double value) {
        setAmount(value.intValue());
        consumer.accept(this.copy());
    }

    public void setAmount(int amount) {
        this.amount = amount;
    }

    public static class Serializer implements SkillBonus.Serializer {
        @Override
        public GrantItemBonus deserialize(JsonObject json) throws JsonParseException {
            ResourceLocation itemId = ResourceLocation.parse(json.get("item_id").getAsString());
            int amount = SerializationHelper.getElement(json, "amount").getAsInt();
            return new GrantItemBonus(itemId, amount);
        }

        @Override
        public void serialize(JsonObject json, SkillBonus<?> bonus) {
            if (!(bonus instanceof GrantItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            json.addProperty("item_id", aBonus.itemId.toString());
            json.addProperty("amount", aBonus.amount);
        }

        @Override
        public GrantItemBonus deserialize(CompoundTag tag) {
            ResourceLocation itemId = ResourceLocation.parse(tag.getString("item_id"));
            int amount = tag.getInt("amount");
            return new GrantItemBonus(itemId, amount);
        }

        @Override
        public CompoundTag serialize(SkillBonus<?> bonus) {
            if (!(bonus instanceof GrantItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            tag.putString("item_id", aBonus.itemId.toString());
            tag.putInt("amount", aBonus.amount);
            return tag;
        }

        @Override
        public GrantItemBonus deserialize(FriendlyByteBuf buf) {
            ResourceLocation itemId = buf.readResourceLocation();
            int duration = buf.readInt();
            return new GrantItemBonus(itemId, duration);
        }

        @Override
        public void serialize(FriendlyByteBuf buf, SkillBonus<?> bonus) {
            if (!(bonus instanceof GrantItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            buf.writeResourceLocation(aBonus.itemId);
            buf.writeInt(aBonus.amount);
        }

        @Override
        public SkillBonus<?> createDefaultInstance() {
            return new GrantItemBonus(ForgeRegistries.ITEMS.getKey(Items.DIAMOND), 64);
        }
    }
}

package net.silentchaos512.scalinghealth.capability;

import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.Mob;
import net.minecraftforge.common.capabilities.*;
import net.minecraftforge.common.util.LazyOptional;
import net.silentchaos512.scalinghealth.ScalingHealth;
import net.silentchaos512.scalinghealth.config.SHConfig;
import net.silentchaos512.scalinghealth.event.DifficultyEvents;
import net.silentchaos512.scalinghealth.utils.MobDifficultyHandler;
import net.silentchaos512.scalinghealth.utils.config.SHDifficulty;
import net.silentchaos512.scalinghealth.utils.config.SHMobs;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;

public class DifficultyAffectedCapability implements IDifficultyAffected, ICapabilitySerializable<CompoundTag> {
    public static Capability<IDifficultyAffected> INSTANCE = CapabilityManager.get(new CapabilityToken<>() {});;
    public static ResourceLocation NAME = ScalingHealth.getId("difficulty_affected");

    private static final String NBT_BLIGHT = "Blight";
    private static final String NBT_DIFFICULTY = "Difficulty";

    private final LazyOptional<IDifficultyAffected> holder = LazyOptional.of(() -> this);

    private float difficulty;
    private boolean blight;
    private boolean processed;

    @Override
    public float getDifficulty() {
        return difficulty;
    }

    @Override
    public void setDifficulty(Mob mob) {
        difficulty = (float) ((Math.random()*(0.1)+0.95) * SHDifficulty.areaDifficulty(mob.level(), mob.blockPosition()));
    }

    @Override
    public void forceDifficulty(float diff) {
        difficulty = diff;
    }

    @Override
    public boolean isBlight() {
        return blight;
    }

    @Override
    public void setIsBlight(boolean value) {
        blight = value;
    }

    @Override
    public void setProcessed(boolean value) {
        this.processed = value;
    }

    @Override
    public void tick(Mob entity) {
        if (!processed && entity.isAlive() && entity.tickCount > 2) {
            setDifficulty(entity);
            MobDifficultyHandler.process(entity, this);
            processed = true;

            if (ScalingHealth.LOGGER.isDebugEnabled() && SHConfig.SERVER.debugLogEntitySpawns.get()) {
                ScalingHealth.LOGGER.debug(DifficultyEvents.MARKER, "Processed {} -> difficulty={}, isBlight={}", entity, difficulty, blight);
            }
        }
    }

    @Nonnull
    @Override
    public <T> LazyOptional<T> getCapability(@Nonnull Capability<T> cap, @Nullable Direction side) {
        return INSTANCE.orEmpty(cap, holder);
    }

    @Override
    public CompoundTag serializeNBT() {
        CompoundTag nbt = new CompoundTag();
        nbt.putBoolean(NBT_BLIGHT, blight);
        nbt.putFloat(NBT_DIFFICULTY, difficulty);
        return nbt;
    }

    @Override
    public void deserializeNBT(CompoundTag nbt) {
        blight = nbt.getBoolean(NBT_BLIGHT);
        difficulty = nbt.getFloat(NBT_DIFFICULTY);
    }

    public static boolean canAttachTo(ICapabilityProvider entity) {
        return entity instanceof Mob
                && !entity.getCapability(INSTANCE).isPresent()
                && SHMobs.allowsDifficultyChanges((Mob) entity);
    }
}

