package net.silentchaos512.scalinghealth.event;

import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.TamableAnimal;
import net.minecraftforge.event.entity.living.LivingEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import net.silentchaos512.scalinghealth.ScalingHealth;
import net.silentchaos512.scalinghealth.objects.item.HeartCrystal;
import net.silentchaos512.scalinghealth.resources.mechanics.SHMechanics;
import net.silentchaos512.scalinghealth.utils.config.EnabledFeatures;

@Mod.EventBusSubscriber(modid = ScalingHealth.MOD_ID, bus = Mod.EventBusSubscriber.Bus.FORGE)
public class PetEventHandler {
    @SubscribeEvent
    public static void onLivingUpdate(LivingEvent.LivingTickEvent event) {
        double regenDelay = SHMechanics.getMechanics().mobMechanics().pets().petsRegenDelay();
        if (regenDelay <= 0)
            return;

        LivingEntity entity = event.getEntity();
        if (entity != null && !entity.level().isClientSide) {
            boolean fullHp = entity.getHealth() == entity.getMaxHealth();
            boolean isTamed = entity instanceof TamableAnimal && ((TamableAnimal) entity).isTame();
            boolean isRegenTime = entity.invulnerableTime <= 0 && entity.tickCount % regenDelay == 0;
            if (isTamed && isRegenTime && !fullHp)
                entity.heal(2f);
        }
    }

    @SubscribeEvent
    public static void onPetInteraction(PlayerInteractEvent.EntityInteractSpecific event){
        if(!EnabledFeatures.petBonusHpEnabled() ||
                !(event.getItemStack().getItem() instanceof HeartCrystal) ||
                !(event.getTarget() instanceof TamableAnimal))
            return;

        TamableAnimal pet = (TamableAnimal) event.getTarget();
        if(!pet.isTame())
            return;

        if(pet.level().isClientSide) {
            event.setCancellationResult(InteractionResult.SUCCESS);
            event.setCanceled(true);
            return;
        }

        HeartCrystal heart = (HeartCrystal) event.getItemStack().getItem();
        heart.increasePetHp(event.getEntity(), pet, event.getItemStack());
    }
}

package net.silentchaos512.scalinghealth.objects.item;

import net.minecraft.Util;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.network.chat.Component;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.stats.Stats;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.TamableAnimal;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Rarity;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.level.Level;
import net.silentchaos512.scalinghealth.ScalingHealth;
import net.silentchaos512.scalinghealth.capability.IPlayerData;
import net.silentchaos512.scalinghealth.capability.PetHealthCapability;
import net.silentchaos512.scalinghealth.resources.mechanics.SHMechanics;
import net.silentchaos512.scalinghealth.utils.ParticleUtils;
import net.silentchaos512.scalinghealth.utils.SoundUtils;
import net.silentchaos512.scalinghealth.utils.config.SHPlayers;

import javax.annotation.Nullable;
import java.util.List;

public abstract class StatBoosterItem extends Item {
    public StatBoosterItem(Properties properties) {
        super(properties);
    }

    private boolean usedForPet = false;

    @Override
    public void appendHoverText(ItemStack stack, @Nullable Level worldIn, List<Component> tooltip, TooltipFlag flagIn) {
        tooltip.add(Component.translatable(this.getDescriptionId() + ".desc"));
    }

    @Override
    public Rarity getRarity(ItemStack stack) {
        return Rarity.RARE;
    }

    @Override
    public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand handIn) {
        ItemStack stack = player.getItemInHand(handIn);
        if(usedForPet) {
            if(world.isClientSide) usedForPet = false;
            return new InteractionResultHolder<>(InteractionResult.FAIL, stack);
        }


        final boolean statIncreaseAllowed = isStatIncreaseAllowed(player);
        final int levelRequirement = getLevelCost(player);

        // Does player have enough XP?
        if (player.experienceLevel < levelRequirement) {
            if (world.isClientSide) {
                String translationKey = "item.scalinghealth.stat_booster.notEnoughXP";
                player.sendSystemMessage(Component.translatable(translationKey, levelRequirement));
            }
            return new InteractionResultHolder<>(InteractionResult.PASS, stack);
        }

        if (!world.isClientSide) {
            // May be used as a healing item even if there is no stat increase
            final boolean consumed = shouldConsume(player);
            if (consumed) {
                extraConsumeEffect(player);
            }

            // End here if stat increases are not allowed
            if (!statIncreaseAllowed) {
                return useAsConsumable(world, player, stack, levelRequirement, consumed);
            }

            // Increase stat, consume item
            return useAsStatIncreaseItem(player, stack, levelRequirement);
        }
        else if(shouldConsume(player) || isStatIncreaseAllowed(player))
            spawnParticlesAndPlaySound(player);

        return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
    }

    public void increasePetHp(Player player, TamableAnimal pet, ItemStack stack){
        //check config

        int levelRequirement = getLevelCost(player);
        if (player.experienceLevel < levelRequirement) {
            String translationKey = "item.scalinghealth.stat_booster.notEnoughXP";
            player.sendSystemMessage(Component.translatable(translationKey, levelRequirement));
            return;
        }

        usedForPet = true;
        pet.getCapability(PetHealthCapability.INSTANCE).ifPresent(data -> data.addHealth(SHMechanics.getMechanics().mobMechanics().pets().petsHealthCrystalGain(), pet));
        stack.shrink(1);
        consumeLevels(player, levelRequirement);
        player.awardStat(Stats.ITEM_USED.get(this));
    }

    protected abstract int getLevelCost(Player player);

    protected abstract boolean isStatIncreaseAllowed(Player player);

    protected abstract boolean shouldConsume(Player player);

    protected abstract void extraConsumeEffect(Player player);

    protected abstract void increaseStat(Player player);

    protected abstract ParticleOptions getParticleType();

    protected abstract SoundEvent getSoundEffect();

    private InteractionResultHolder<ItemStack> useAsConsumable(Level world, Player player, ItemStack stack, int levelRequirement, boolean consumed) {
        if (consumed) {
            world.playSound(null, player.blockPosition(), SoundEvents.PLAYER_BURP, SoundSource.PLAYERS,
                    0.5f, 1 + 0.1f * (float) ScalingHealth.RANDOM.nextGaussian());
            stack.shrink(1);
            consumeLevels(player, levelRequirement);
            player.awardStat(Stats.ITEM_USED.get(this));
            return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
        }
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    }

    private InteractionResultHolder<ItemStack> useAsStatIncreaseItem(Player player, ItemStack stack, int levelRequirement) {
        increaseStat(player);
        stack.shrink(1);
        consumeLevels(player, levelRequirement);
        player.awardStat(Stats.ITEM_USED.get(this));
        IPlayerData.sendUpdatePacketTo(player);
        return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
    }

    private void spawnParticlesAndPlaySound(Player player) {
        ScalingHealth.LOGGER.debug("StatBoosterItem effect!");
        ParticleUtils.spawn(getParticleType(), 40, player);
        SoundUtils.play(player, getSoundEffect());
    }

    private static void consumeLevels(Player player, int amount) {
        player.giveExperienceLevels(-amount);
        SHPlayers.getPlayerData(player).updateStats(player);
    }
}

package net.silentchaos512.scalinghealth.utils;

import net.minecraft.ChatFormatting;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.boss.enderdragon.EnderDragon;
import net.minecraft.world.entity.boss.wither.WitherBoss;
import net.minecraft.world.entity.monster.Enemy;
import net.minecraftforge.network.PacketDistributor;
import net.minecraftforge.registries.ForgeRegistries;
import net.silentchaos512.scalinghealth.ScalingHealth;
import net.silentchaos512.scalinghealth.capability.IDifficultyAffected;
import net.silentchaos512.scalinghealth.event.BlightHandler;
import net.silentchaos512.scalinghealth.event.CommonEvents;
import net.silentchaos512.scalinghealth.network.ClientBlightMessage;
import net.silentchaos512.scalinghealth.network.Network;
import net.silentchaos512.scalinghealth.utils.config.EnabledFeatures;
import net.silentchaos512.scalinghealth.utils.config.SHDifficulty;
import net.silentchaos512.scalinghealth.utils.config.SHMobs;
import net.silentchaos512.scalinghealth.utils.mode.MobHealthMode;
import net.silentchaos512.utils.MathUtils;

public final class MobDifficultyHandler {
    private MobDifficultyHandler() {}

    public static void process(Mob entity, IDifficultyAffected data) {
        if (!entity.isAlive()) return;
        setEntityProperties(entity, data, shouldBecomeBlight(entity, data.getDifficulty()));
    }

    public static boolean shouldBecomeBlight(Mob entity, float difficulty) {
        if (!SHMobs.canBecomeBlight(entity))    return false;

        double chance = getBlightChance(difficulty);
        if(chance == 1)    return true;

        return MathUtils.tryPercentage(ScalingHealth.RANDOM, chance);
    }

    private static double getBlightChance(float difficulty) {
        return SHMobs.blightChance() * difficulty / SHDifficulty.maxValue();
    }

    public static void setEntityProperties(Mob entity, IDifficultyAffected data, boolean makeBlight) {
        if (!entity.isAlive()) return;

        boolean isHostile = entity instanceof Enemy;

        if (makeBlight) {
            data.setIsBlight(true);
            ClientBlightMessage msg = new ClientBlightMessage(entity.getId());
            Network.channel.send(PacketDistributor.TRACKING_ENTITY.with(()->entity), msg);

            BlightHandler.applyBlightPotionEffects(entity);
            //TODO no good in code method for determining if an entity is a boss or not, switch to tag?
            if(entity instanceof WitherBoss || entity instanceof EnderDragon) {
                Component blight = Component.translatable("misc.scalinghealth.blight", entity.getDisplayName()).copy().withStyle(ChatFormatting.DARK_PURPLE);
                entity.setCustomName(blight);
            }
        }

        //Get difficulty after making blight or not. This will determine if a blight's diff is multiplied
        final float difficulty = data.affectiveDifficulty();
        if(difficulty <= 0) return;

        // Random potion effect
        SHMobs.getMobEffects().forEach(c -> c.tryApply(entity, difficulty));

        if(EnabledFeatures.mobHpIncreaseEnabled()) {
            double healthBoost = difficulty;

            double healthMultiplier = isHostile
                    ? SHMobs.healthHostileMultiplier()
                    : SHMobs.healthPassiveMultiplier();

            healthBoost *= healthMultiplier;

            //TODO test... wtf was i doing here?
            //healthBoost += 2 * healthMultiplier * difficulty * ScalingHealth.RANDOM.nextFloat();

            if(CommonEvents.spawnerSpawns.contains(entity.getUUID())){
                healthBoost *= SHMobs.spawnerModifier();
                CommonEvents.spawnerSpawns.remove(entity.getUUID());
            }

            // Apply extra health and damage.
            MobHealthMode mode = SHMobs.getHealthMode();
            ModifierHandler.setMaxHealth(entity, mode.getModifierHealth(healthBoost, entity.getAttribute(Attributes.MAX_HEALTH).getBaseValue()), mode.getOp());
        }

        // Increase attack damage.
        if(EnabledFeatures.mobDamageIncreaseEnabled()) {
            double damageBoost;

            float diffIncrease = difficulty * ScalingHealth.RANDOM.nextFloat();
            damageBoost = diffIncrease * SHMobs.damageBoostScale();
            // Clamp the value so it doesn't go over the maximum config.
            double max = SHMobs.maxDamageBoost();
            if (max > 0f) {
                damageBoost = Mth.clamp(damageBoost, 0, max);
            }

            ResourceLocation loc = ForgeRegistries.ENTITY_TYPES.getKey(entity.getType());
            if (loc != null && !SHDifficulty.getDamageBlacklistedMods().contains(loc.getNamespace()))
                ModifierHandler.addAttackDamage(entity, damageBoost, AttributeModifier.Operation.ADDITION);
        }
    }
}

